1: import { NextResponse } from 'next/server';
2: import { db } from '@/lib/db';
3: import { getSessionFromRequest } from '@/lib/api-auth';
4: import { grantExp } from '@/lib/gamification/grant-exp';
5: import { awardBadgeIfEarned } from '@/lib/gamification/badge-checker';
6: import { createNotification } from '@/lib/notifications';
7: 
8: export const dynamic = 'force-dynamic';
9: 
10: interface RouteContext {
11:   params: Promise<{ courseId: string }>;
12: }
13: 
14: /**
15:  * POST /api/courses/[courseId]/submissions/grade
16:  * Evaluates and returns a student submission with score, feedback, EXP incentives, and notification.
17:  */
18: export async function POST(request: Request, context: RouteContext) {
19:   try {
20:     const session = await getSessionFromRequest(request);
21:     if (!session) {
22:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
23:     }
24: 
25:     const role = (session.user.role as string).toUpperCase();
26:     if (role !== 'PROFESSOR' && role !== 'TEACHER' && role !== 'ADMIN') {
27:       return NextResponse.json({ message: 'Instructors only.' }, { status: 403 });
28:     }
29: 
30:     const { courseId } = await context.params;
31:     const body = await request.json();
32:     const { submissionId, grade: rawGrade, feedback } = body;
33: 
34:     if (!submissionId || rawGrade === undefined || rawGrade === null) {
35:       return NextResponse.json({ message: 'submissionId and grade are required.' }, { status: 400 });
36:     }
37: 
38:     const course = await db.course.findUnique({
39:       where: { id: courseId },
40:       select: { id: true, instructorId: true, code: true, instituteId: true },
41:     });
42: 
43:     if (!course) {
44:       return NextResponse.json({ message: 'Course not found.' }, { status: 404 });
45:     }
46: 
47:     if (role !== 'ADMIN' && course.instructorId !== session.user.id) {
48:       return NextResponse.json({ message: 'You are not the instructor for this course.' }, { status: 403 });
49:     }
50: 
51:     const existingSubmission = await db.studentSubmission.findUnique({
52:       where: { id: submissionId },
53:       include: {
54:         syllabusItem: {
55:           select: {
56:             id: true,
57:             title: true,
58:             type: true,
59:             maxPoints: true,
60:             courseId: true,
61:           },
62:         },
63:       },
64:     });
65: 
66:     if (!existingSubmission || existingSubmission.syllabusItem.courseId !== courseId) {
67:       return NextResponse.json({ message: 'Submission not found in this course.' }, { status: 404 });
68:     }
69: 
70:     let grade = Math.max(0, Number(rawGrade));
71:     const maxPoints = existingSubmission.syllabusItem.maxPoints;
72:     if (maxPoints !== null && maxPoints !== undefined) {
73:       grade = Math.min(maxPoints, grade);
74:     }
75: 
76:     // Update submission status to RETURNED
77:     const updatedSubmission = await db.studentSubmission.update({
78:       where: { id: submissionId },
79:       data: {
80:         grade,
81:         status: 'RETURNED',
82:         isReturned: true,
83:       },
84:       include: {
85:         student: {
86:           select: { id: true, name: true, email: true },
87:         },
88:         attachments: true,
89:       },
90:     });
91: 
92:     // Save private feedback comment if provided
93:     if (feedback && typeof feedback === 'string' && feedback.trim().length > 0) {
94:       await db.privateComment.create({
95:         data: {
96:           courseId,
97:           senderId: session.user.id,
98:           recipientId: existingSubmission.studentId,
99:           content: feedback.trim(),
100:         },
101:       });
102:     }
103: 
104:     // Evaluate Grade Incentive Rules for bonus EXP
105:     try {
106:       const courseRules = await db.gradeIncentiveRule.findMany({
107:         where: { courseId, isActive: true },
108:       });
109: 
110:       for (const rule of courseRules) {
111:         if (grade >= rule.gradeMin) {
112:           await grantExp({
113:             userId: existingSubmission.studentId,
114:             amount: rule.bonusExp,
115:             reason: `Grade Incentive: ${rule.label} (${grade} pts in ${course.code})`,
116:             source: 'grade_incentive',
117:             courseId,
118:           });
119:         }
120:       }
121: 
122:       if (maxPoints && grade >= maxPoints) {
123:         await awardBadgeIfEarned(existingSubmission.studentId, 'perfect-score');
124:       }
125:     } catch (incentiveErr) {
126:       console.error('GRADE_INCENTIVE_ERROR', incentiveErr);
127:     }
128: 
129:     // Dispatch in-app notification to the student
130:     const itemTypeLabel = existingSubmission.syllabusItem.type === 'QUIZ' ? 'Quiz' : 'Assignment';
131:     const scoreDisplay = maxPoints ? `${grade}/${maxPoints}` : `${grade}`;
132:     await createNotification({
133:       userId: existingSubmission.studentId,
134:       type: 'GRADE',
135:       title: `${itemTypeLabel} Graded: ${existingSubmission.syllabusItem.title}`,
136:       message: `Your instructor returned a score of ${scoreDisplay} for ${existingSubmission.syllabusItem.title}.`,
137:       link: `/${courseId}/grades`,
138:     });
139: 
140:     return NextResponse.json({
141:       success: true,
142:       submission: {
143:         id: updatedSubmission.id,
144:         syllabusItemId: updatedSubmission.syllabusItemId,
145:         studentId: updatedSubmission.studentId,
146:         studentName: updatedSubmission.student.name,
147:         grade: updatedSubmission.grade,
148:         status: updatedSubmission.status,
149:         isReturned: updatedSubmission.isReturned,
150:         submittedAt: updatedSubmission.submittedAt?.toISOString() || null,
151:         attachments: updatedSubmission.attachments,
152:       },
153:     });
154:   } catch (error) {
155:     console.error('GRADE_SUBMISSION_POST_ERROR', error);
156:     return NextResponse.json({ message: 'Failed to grade submission.' }, { status: 500 });
157:   }
158: }
159:

1: import { NextResponse } from 'next/server';
2: import { db } from '@/lib/db';
3: import { getSessionFromRequest } from '@/lib/api-auth';
4: 
5: export const dynamic = "force-dynamic";
6: 
7: interface RouteContext {
8:   params: Promise<{ courseId: string }>;
9: }
10: 
11: /**
12:  * POST /api/courses/[courseId]/submissions
13:  * Submits or saves a draft submission for a syllabus item.
14:  */
15: /**
16:  * GET /api/courses/[courseId]/submissions?syllabusItemId=...
17:  * Fetches submission(s) for a syllabus item.
18:  * Students get their own submission; Instructors get all student submissions.
19:  */
20: export async function GET(request: Request, context: RouteContext) {
21:   try {
22:     const session = await getSessionFromRequest(request);
23:     if (!session) {
24:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
25:     }
26: 
27:     const { courseId } = await context.params;
28:     const { searchParams } = new URL(request.url);
29:     const syllabusItemId = searchParams.get('syllabusItemId');
30: 
31:     if (!syllabusItemId) {
32:       return NextResponse.json({ message: 'syllabusItemId query param is required.' }, { status: 400 });
33:     }
34: 
35:     const role = (session.user.role as string).toUpperCase();
36:     const isInstructor = role === 'PROFESSOR' || role === 'TEACHER' || role === 'ADMIN';
37: 
38:     if (isInstructor) {
39:       const submissions = await db.studentSubmission.findMany({
40:         where: { syllabusItemId },
41:         include: {
42:           student: {
43:             select: {
44:               id: true,
45:               name: true,
46:               email: true,
47:               studentNumber: true,
48:               avatarUrl: true,
49:             },
50:           },
51:           attachments: {
52:             select: { id: true, type: true, url: true, fileName: true },
53:           },
54:         },
55:         orderBy: { submittedAt: 'desc' },
56:       });
57: 
58:       return NextResponse.json({ submissions });
59:     }
60: 
61:     // Student view: their own submission
62:     const submission = await db.studentSubmission.findUnique({
63:       where: {
64:         syllabusItemId_studentId: {
65:           syllabusItemId,
66:           studentId: session.user.id,
67:         },
68:       },
69:       include: {
70:         attachments: {
71:           select: { id: true, type: true, url: true, fileName: true },
72:         },
73:       },
74:     });
75: 
76:     return NextResponse.json({ submission: submission || null });
77:   } catch (error) {
78:     console.error('COURSE_SUBMISSIONS_GET_ERROR', error);
79:     return NextResponse.json({ message: 'Failed to fetch submission.' }, { status: 500 });
80:   }
81: }
82: 
83: /**
84:  * POST /api/courses/[courseId]/submissions
85:  * Submits or saves a draft submission for a syllabus item.
86:  * Supports multiple file attachments and unsubmit (status: 'DRAFT').
87:  */
88: export async function POST(request: Request, context: RouteContext) {
89:   try {
90:     const session = await getSessionFromRequest(request);
91:     if (!session) {
92:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
93:     }
94: 
95:     const { courseId } = await context.params;
96:     const body = await request.json();
97:     const { syllabusItemId, status = 'SUBMITTED', attachmentUrl, fileName, attachments } = body;
98: 
99:     if (!syllabusItemId) {
100:       return NextResponse.json({ message: 'syllabusItemId is required.' }, { status: 400 });
101:     }
102: 
103:     const syllabusItem = await db.syllabusItem.findFirst({
104:       where: { id: syllabusItemId, courseId },
105:     });
106: 
107:     if (!syllabusItem) {
108:       return NextResponse.json({ message: 'Syllabus item not found for this course.' }, { status: 404 });
109:     }
110: 
111:     // Check existing submission for unsubmit restrictions
112:     const existing = await db.studentSubmission.findUnique({
113:       where: {
114:         syllabusItemId_studentId: {
115:           syllabusItemId,
116:           studentId: session.user.id,
117:         },
118:       },
119:     });
120: 
121:     if (existing && status === 'DRAFT') {
122:       if (existing.isReturned || existing.grade !== null) {
123:         return NextResponse.json(
124:           { message: 'This assignment has already been graded/returned and cannot be unsubmitted.' },
125:           { status: 400 }
126:         );
127:       }
128:     }
129: 
130:     const submission = await db.studentSubmission.upsert({
131:       where: {
132:         syllabusItemId_studentId: {
133:           syllabusItemId,
134:           studentId: session.user.id,
135:         },
136:       },
137:       update: {
138:         status,
139:         submittedAt: status === 'SUBMITTED' ? new Date() : existing?.submittedAt ?? null,
140:       },
141:       create: {
142:         syllabusItemId,
143:         studentId: session.user.id,
144:         status,
145:         submittedAt: status === 'SUBMITTED' ? new Date() : null,
146:       },
147:     });
148: 
149:     // Handle single attachment (legacy/backward compatibility)
150:     if (attachmentUrl) {
151:       await db.submissionAttachment.create({
152:         data: {
153:           submissionId: submission.id,
154:           type: 'LINK',
155:           url: attachmentUrl,
156:           fileName: fileName || 'Submission Link',
157:         },
158:       });
159:     }
160: 
161:     // Handle multiple attachments
162:     if (Array.isArray(attachments) && attachments.length > 0) {
163:       await db.submissionAttachment.createMany({
164:         data: attachments.map((att: { url: string; fileName?: string; type?: string }) => ({
165:           submissionId: submission.id,
166:           type: att.type || 'FILE',
167:           url: att.url,
168:           fileName: att.fileName || 'Attachment',
169:         })),
170:       });
171:     }
172: 
173:     const updated = await db.studentSubmission.findUnique({
174:       where: { id: submission.id },
175:       include: {
176:         attachments: {
177:           select: { id: true, type: true, url: true, fileName: true },
178:         },
179:       },
180:     });
181: 
182:     return NextResponse.json({
183:       success: true,
184:       submission: {
185:         id: updated!.id,
186:         status: updated!.status,
187:         grade: updated!.grade,
188:         isReturned: updated!.isReturned,
189:         submittedAt: updated!.submittedAt?.toISOString() || null,
190:         attachments: updated!.attachments,
191:       },
192:     });
193:   } catch (error) {
194:     console.error('COURSE_SUBMISSIONS_POST_ERROR', error);
195:     return NextResponse.json({ message: 'Failed to submit assignment.' }, { status: 500 });
196:   }
197: }
