apps/web/src/app/api/courses/route.ts.numberedContent:
1: import { NextResponse } from 'next/server';
2: import { db } from '@/lib/db';
3: import { getSessionFromRequest } from '@/lib/api-auth';
4: 
5: export const dynamic = "force-dynamic";
6: 
7: /**
8:  * GET /api/courses?institute=ics&page=1&limit=15
9:  * Fetches lightweight course list for the authenticated user/institute.
10:  */
11: export async function GET(request: Request) {
12:   try {
13:     const session = await getSessionFromRequest(request);
14:     if (!session) {
15:       return NextResponse.json({ message: 'Not authenticated.' }, { status: 401 });
16:     }
17: 
18:     const { searchParams } = new URL(request.url);
19:     const instituteCode = searchParams.get('institute') || 'ics';
20:     const page = Math.max(parseInt(searchParams.get('page') || '1', 10), 1);
21:     const limit = Math.min(Math.max(parseInt(searchParams.get('limit') || '15', 10), 1), 50);
22:     const skip = (page - 1) * limit;
23: 
24:     const institute = await db.institute.findUnique({
25:       where: { code: instituteCode.toLowerCase() },
26:       select: { id: true, name: true, code: true },
27:     });
28: 
29:     if (!institute) {
30:       return NextResponse.json({ message: 'Institute not found.' }, { status: 404 });
31:     }
32: 
33:     const role = (session.user.role || 'STUDENT').toUpperCase();
34:     let courses: any[] = [];
35:     let totalCount = 0;
36: 
37:     if (role === 'STUDENT') {
38:       const whereCondition = {
39:         studentId: session.user.id,
40:         status: 'APPROVED',
41:         course: {
42:           instituteId: institute.id,
43:           isArchived: false,
44:         },
45:       };
46: 
47:       const [enrollments, count] = await Promise.all([
48:         db.enrollment.findMany({
49:           where: whereCondition,
50:           select: {
51:             course: {
52:               select: {
53:                 id: true,
54:                 code: true,
55:                 courseCode: true,
56:                 title: true,
57:                 description: true,
58:                 room: true,
59:                 section: true,
60:                 subject: true,
61:                 coverImage: true,
62:                 instructor: {
63:                   select: {
64:                     name: true,
65:                   },
66:                 },
67:               },
68:             },
69:           },
70:           orderBy: { displayOrderIndex: 'asc' },
71:           skip,
72:           take: limit,
73:         }),
74:         db.enrollment.count({ where: whereCondition }),
75:       ]);
76: 
77:       totalCount = count;
78:       courses = enrollments.map((e) => ({
79:         id: e.course.id,
80:         code: e.course.code,
81:         courseCode: e.course.courseCode || e.course.code,
82:         title: e.course.title,
83:         description: e.course.description,
84:         room: e.course.room,
85:         section: e.course.section,
86:         subject: e.course.subject,
87:         coverImage: e.course.coverImage,
88:         instructorName: e.course.instructor?.name || 'Instructor',
89:       }));
90:     } else if (role === 'PROFESSOR' || role === 'TEACHER') {
91:       const whereCondition = {
92:         instructorId: session.user.id,
93:         instituteId: institute.id,
94:         isArchived: false,
95:       };
96: 
97:       const [taughtCourses, count] = await Promise.all([
98:         db.course.findMany({
99:           where: whereCondition,
100:           select: {
101:             id: true,
102:             code: true,
103:             courseCode: true,
104:             title: true,
105:             description: true,
106:             room: true,
107:             section: true,
108:             subject: true,
109:             coverImage: true,
110:             _count: {
111:               select: { enrollments: true },
112:             },
113:           },
114:           orderBy: { code: 'asc' },
115:           skip,
116:           take: limit,
117:         }),
118:         db.course.count({ where: whereCondition }),
119:       ]);
120: 
121:       totalCount = count;
122:       courses = taughtCourses.map((c) => ({
123:         id: c.id,
124:         code: c.code,
125:         courseCode: c.courseCode || c.code,
126:         title: c.title,
127:         description: c.description,
128:         room: c.room,
129:         section: c.section,
130:         subject: c.subject,
131:         coverImage: c.coverImage,
132:         instructorName: session.user.name,
133:         studentCount: c._count?.enrollments || 0,
134:       }));
135:     } else {
136:       // Admin view - all active courses for institute
137:       const whereCondition = {
138:         instituteId: institute.id,
139:         isArchived: false,
140:       };
141: 
142:       const [allCourses, count] = await Promise.all([
143:         db.course.findMany({
144:           where: whereCondition,
145:           select: {
146:             id: true,
147:             code: true,
148:             courseCode: true,
149:             title: true,
150:             description: true,
151:             room: true,
152:             section: true,
153:             subject: true,
154:             coverImage: true,
155:             instructor: {
156:               select: { name: true },
157:             },
158:           },
159:           orderBy: { code: 'asc' },
160:           skip,
161:           take: limit,
162:         }),
163:         db.course.count({ where: whereCondition }),
164:       ]);
165: 
166:       totalCount = count;
167:       courses = allCourses.map((c) => ({
168:         id: c.id,
169:         code: c.code,
170:         courseCode: c.courseCode || c.code,
171:         title: c.title,
172:         description: c.description,
173:         room: c.room,
174:         section: c.section,
175:         subject: c.subject,
176:         coverImage: c.coverImage,
177:         instructorName: c.instructor?.name || 'Unassigned',
178:       }));
179:     }
180: 
181:     return NextResponse.json(
182:       {
183:         courses,
184:         pagination: {
185:           page,
186:           limit,
187:           totalCount,
188:           totalPages: Math.ceil(totalCount / limit),
189:           hasMore: skip + courses.length < totalCount,
190:         },
191:       },
192:       {
193:         headers: {
194:           'Cache-Control': 'private, s-maxage=60, stale-while-revalidate=300',
195:         },
196:       }
197:     );
198:   } catch (error) {
199:     console.error('COURSES_API_ERROR', error);
200:     return NextResponse.json({ message: 'Failed to fetch courses.' }, { status: 500 });
201:   }
202: }
