apps/web/src/app/api/flashcards/auto-gen.numberedContent:
1: import { NextResponse } from "next/server";
2: import { getSession } from "@/lib/auth-session";
3: import { db } from "@/lib/db";
4: import nlp from "compromise";
5: import AdmZip from "adm-zip";
6: 
7: // ─── Types ───────────────────────────────────────────────────────────────────
8: interface RawCard {
9:   front: string;
10:   back: string;
11:   hint?: string;
12: }
13: 
14: // ─── Constants ───────────────────────────────────────────────────────────────
15: 
16: /** Slide titles to skip entirely (non-educational / instructional) */
17: const IGNORE_TITLES = [
18:   "activity", "task", "question", "objective", "objectives", "summary",
19:   "conclusion", "introduction", "assignment", "homework", "agenda",
20:   "overview", "outline", "table of contents", "references", "bibliography",
21:   "thank you", "thanks", "end", "questions", "review", "recap", "credits",
22:   "disclaimer", "definition", "definitions", "example", "examples", "glossary",
23:   "course overview", "grading system", "course description", "course policies",
24:   "policies", "about me", "about the instructor", "instructor", "course outline",
25:   "syllabus", "requirements", "course requirements", "house rules", "class rules",
26:   "learning outcomes", "learning outcome", "intended learning outcomes", 
27:   "intended learning outcome", "course objectives", "learning objectives"
28: ];
29: 
30: /** Slide title prefixes to skip */
31: const IGNORE_PREFIXES = [
32:   "activity ", "task ", "question ", "module ", "lesson ", "unit ", "example ", "chapter ", "course ", "week "
33: ];
34: 
35: /** Regex to detect meta/instructional headers that shouldn't become cards */
36: const META_HEADER_REGEX =
37:   /\b(note|notes|guide questions|guide question|quiz|activity|task|question|questions|objective|objectives|summary|conclusion|introduction|assignment|homework|agenda|lecture|module|unit|lesson|chapter|instructions|definition|definitions|example|examples|overview|outline|references|bibliography|glossary|index)\b/i;
38: 
39: /** Regex to detect instructional sentences that start with meta phrases */
40: const META_SENTENCE_START_REGEX =
41:   /^(?:(?:\d+(?:\.\d+)*|[a-zA-Z]|[ivxlIVXL]+)[.)]\s*)?(?:by the end of|at the end of|after this|upon completion|in this (?:lesson|chapter|module|unit|course)|students should be able to|learning objectives?|this (?:lesson|chapter|module|unit|course) (?:covers|will cover|introduces|explores|focuses on)|objectives?|agenda|outline|overview|study (?:each of|the following)|read (?:each of|the following)|review (?:each of|the following)|the following topics|please (?:read|study|review|note)|draw\b|write\b|create\b|list\b|mention\b|discuss\b|compare\b|explain\b|identify\b|describe\b|summarize\b|outline\b|provide\b|illustrate\b|demonstrate\b|show\b|state\b|answer\b|understand\b|evaluate\b|analyze\b|conduct\b|recognize\b|record\b|reflect\b|apply\b|design\b|develop\b|assess\b|determine\b)/i;
42: 
43: /** Regex to detect policy sentences (cheating, grading, etc.) ANYWHERE in the sentence */
44: const POLICY_SENTENCE_REGEX =
45:   /\b(?:academic integrity|academic dishonesty|cheating|plagiarism|violation of|penalty for|considered dropped|attend classes|accumulates absences|midterm examination|missed exam|makeup exam|make-up|written evidence|medium of communication|percentage distribution|grading system|lecture grade|laboratory grade)\b/i;
46: 
47: /** Regex to detect non-educational body lines (attributions, names, etc.) */
48: const NON_EDUCATIONAL_LINE_REGEX =
49:   /^(?:(?:presented|prepared|submitted|compiled|created|made|written|reported|developed|designed|facilitated)\s+by\b|(?:group|team)\s+(?:members?|\d)|(?:members?|authors?)\s*:|(?:prof\.?|engr\.?|dr\.?|mr\.?|mrs\.?|ms\.?)\s+[A-Z]|\b(?:BSN|BSIT|BSCS|BSCE|BS\s|AB\s|MA\s|MBA)\b|^[A-Z][a-z]+(?:\s+[A-Z]\.?)+(?:\s+[A-Z][a-z]+)+$)/i;
50: 
51: /** Check if a line looks like a person's name (all title-case words, 2-8 words, no verbs/prepositions) */
52: function looksLikePersonName(text: string): boolean {
53:   const trimmed = text.trim();
54:   if (trimmed.length < 5 || trimmed.length > 80) return false;
55:   const words = trimmed.split(/\s+/);
56:   // Allow up to 8 words to accommodate credentials (e.g., "John Doe, PhD, LPT")
57:   if (words.length < 2 || words.length > 8) return false;
58:   // All words start with uppercase
59:   const allTitleCase = words.every((w) => /^[A-Z]/.test(w));
60:   if (!allTitleCase) return false;
61:   // No common English words that would indicate a phrase, not a name
62:   const hasCommonWord = words.some((w) =>
63:     /^(the|and|for|with|from|that|this|are|was|were|has|have|its|but|not|can|will|into|over|such|than|them|then|also|each|much|most|more|some|very|just|only|both|used|make|made|like|been|does|done|being|about|after|these|those|which|where|there|their|other|would|could|should|every|under)$/i.test(w)
64:   );
65:   if (hasCommonWord) return false;
66:   // Contains a period after a single letter (initial) — strong name signal
67:   if (/\b[A-Z]\./i.test(trimmed)) return true;
68:   // Short enough to be a name (2-3 words)
69:   return words.length <= 3;
70: }
