72: // ─── Varied Question Templates (Mixed Format) ────────────────────────────
73: // Combines 5W1H questions with other question styles for variety:
74: // imperative prompts (Define, Describe, Explain), comparison, and fill-in-blank.
75: 
76: /** Pool of definition-style question phrasings — 5W1H + additional styles */
77: const DEFINITION_TEMPLATES = [
78:   // 5W1H
79:   (s: string) => `What is ${s}?`,
80:   (s: string) => `What is the definition of ${s}?`,
81:   (s: string) => `What is meant by ${s}?`,
82:   (s: string) => `How is ${s} defined?`,
83:   (s: string) => `What does ${s} refer to?`,
84:   // Non-5W1H (Imperative / Statement)
85:   (s: string) => `Define ${s}.`,
86:   (s: string) => `Explain the concept of ${s}.`,
87:   (s: string) => `Describe ${s} in your own words.`,
88:   (s: string) => `In simple terms, explain ${s}.`,
89:   (s: string) => `Identify the key characteristics of ${s}.`,
90:   (s: string) => `Provide a detailed explanation of ${s}.`,
91:   (s: string) => `Elaborate on the meaning of ${s}.`,
92:   (s: string) => `State the definition of ${s}.`,
93:   // Fill-in-the-blank / Completion style
94:   (s: string) => `Complete the thought: The term ${s} refers to...`,
95:   (s: string) => `Briefly summarize the concept of ${s}.`,
96: ];
97: 
98: /** Pool of topic-style question phrasings — 5W1H + additional styles */
99: const TOPIC_TEMPLATES = [
100:   // 5W1H
101:   (s: string) => `What is the significance of ${s}?`,
102:   (s: string) => `Why is ${s} important?`,
103:   (s: string) => `How does ${s} function?`,
104:   (s: string) => `What is the main purpose of ${s}?`,
105:   (s: string) => `What role does ${s} play?`,
106:   (s: string) => `How does ${s} impact the system?`,
107:   // Non-5W1H (Imperative / Statement)
108:   (s: string) => `Explain the role of ${s}.`,
109:   (s: string) => `Describe the function of ${s}.`,
110:   (s: string) => `Give an example that illustrates ${s}.`,
111:   (s: string) => `Summarize the key points of ${s}.`,
112:   (s: string) => `Discuss the importance of ${s}.`,
113:   (s: string) => `Compare ${s} with a related concept.`,
114:   (s: string) => `Outline the main aspects of ${s}.`,
115:   (s: string) => `Provide a brief overview of ${s}.`,
116:   (s: string) => `Elaborate on the topic of ${s}.`,
117:   // Fill-in-the-blank / Completion style
118:   (s: string) => `Complete the thought: The primary function of ${s} is...`,
119: ];
