121: /** Simple deterministic string hash (consistent across runs) */
122: function simpleHash(str: string): number {
123:   let hash = 0;
124:   for (let i = 0; i < str.length; i++) {
125:     hash = ((hash << 5) - hash + str.charCodeAt(i)) | 0;
126:   }
127:   return Math.abs(hash);
128: }
129: 
130: /**
131:  * Pick a varied default question based on a hash of subject + body.
132:  * Same inputs always produce the same output (reproducible), but different
133:  * inputs naturally spread across the template pool.
134:  */
135: function getDefaultQuestion(subject: string, body: string, isDefinition: boolean): string {
136:   const templates = isDefinition ? DEFINITION_TEMPLATES : TOPIC_TEMPLATES;
137:   const index = simpleHash(subject + body) % templates.length;
138:   return templates[index](subject);
139: }
140: 
141: /**
142:  * Content-aware question generator — inspects the answer text to pick the
143:  * most appropriate question type from diverse categories (5W1H + non-5W1H).
144:  */
145: function generateQuestion(subject: string, body: string, isDefinition: boolean = false): string {
146:   // If the subject is already a question, use it directly to prevent "question inception"
147:   if (subject.trim().endsWith("?")) {
148:     return subject.trim().replace(/\?+$/, "?"); // Ensure exactly one question mark
149:   }
150: 
151:   // List Item / Example: If the text starts with a list marker (e.g. "1.", "A)", "ii.")
152:   if (/^(?:\d+(?:\.\d+)*|[a-zA-Z]|[ivxlIVXL]+)[.)]\s/.test(body.trim())) {
153:     // If the subject is plural (ends with 's'), it's likely a list of examples/types
154:     if (subject.toLowerCase().endsWith("s")) {
155:       return `What is an example of ${subject}?`;
156:     }
157:     // Otherwise it's a key point or aspect
158:     return `What is a key aspect of ${subject}?`;
159:   }
160: 
161:   const b = body.toLowerCase();
162: 
163:   // Person / Attribution
164:   if (/(?:developed|invented|created|founded|introduced|proposed|discovered) by/i.test(b))
165:     return `Who developed ${subject}?`;
166: 
167:   // Temporal
168:   if (/\b(1[0-9]{3}|20[0-9]{2})\b/.test(b) ||
169:       /\b(year|century|period|era|decade|date)\b/i.test(b))
170:     return `When did ${subject} occur?`;
171: 
172:   // Location
173:   if (/\b(located|found in|region|country|area|continent|city|place)\b/i.test(b))
174:     return `Where is ${subject} located?`;
175: 
176:   // Cause / Effect
177:   if (/\b(because|therefore|causes?|leads? to|results? in|due to|consequence|effect)\b/i.test(b))
178:     return `What causes ${subject}?`;
179: 
180:   // Process / Steps
181:   if (/\b(first|then|next|finally|step|process|stage|phase|procedure)\b/i.test(b))
182:     return `How does the process of ${subject} work?`;
183: 
184:   // Comparison
185:   if (/\b(unlike|whereas|compared to|differ|contrast|while|however|distinction)\b/i.test(b))
186:     return `How does ${subject} differ from related concepts?`;
187: 
188:   // Example
189:   if (/\b(example|instance|such as|like|including|e\.g\.)\b/i.test(b))
190:     return `What is an example of ${subject}?`;
191: 
192:   // Purpose / Function
193:   if (/\b(used to|allows?|enables?|helps?|purpose|function|role of|serves?)\b/i.test(b))
194:     return `What is the purpose of ${subject}?`;
195: 
196:   // Significance / Importance
197:   if (/\b(important|significant|key|critical|essential|major|crucial|vital)\b/i.test(b))
198:     return `Why is ${subject} important?`;
199: 
200:   // Quantity / Types
201:   if (/\b(three|four|five|six|seven|eight|nine|ten|several|many|numerous|multiple)\s+(?:types?|kinds?|forms?|parts?|categories|components?)\b/i.test(b))
202:     return `How many types of ${subject} are there?`;
203: 
204:   // Default — varied definition/topic question (mixed 5W1H + non-5W1H format)
205:   return getDefaultQuestion(subject, body, isDefinition);
206: }
