208: // ─── Deduplication ───────────────────────────────────────────────────────────
209: 
210: /** Normalize text for dedup comparison: lowercase, strip punctuation, collapse spaces */
211: function normalizeForDedup(text: string): string {
212:   return text
213:     .toLowerCase()
214:     .replace(/[^a-z0-9\s]/g, "")
215:     .replace(/\s+/g, " ")
216:     .trim();
217: }
218: 
219: /**
220:  * Jaccard similarity on word sets — measures how much two strings overlap.
221:  * 0 = nothing in common, 1 = identical word sets.
222:  */
223: function jaccardSimilarity(a: string, b: string): number {
224:   const setA = new Set(normalizeForDedup(a).split(" ").filter(Boolean));
225:   const setB = new Set(normalizeForDedup(b).split(" ").filter(Boolean));
226:   if (setA.size === 0 && setB.size === 0) return 1;
227:   let intersection = 0;
228:   for (const w of setA) { if (setB.has(w)) intersection++; }
229:   const union = setA.size + setB.size - intersection;
230:   return union === 0 ? 1 : intersection / union;
231: }
232: 
233: /**
234:  * Remove cards with:
235:  * 1. Near-identical front text (exact-normalized dedup)
236:  * 2. Near-duplicate backs (Jaccard > 0.65) — keep the shorter/better one
237:  */
238: function deduplicateCards(cards: RawCard[]): RawCard[] {
239:   // Step 1: dedup on normalized front, but aggregate backs for identical questions!
240:   const byFront = new Map<string, RawCard>();
241:   for (const card of cards) {
242:     const key = normalizeForDedup(card.front);
243:     if (!byFront.has(key)) {
244:       // Deep copy to avoid mutating the original array elements
245:       byFront.set(key, { ...card });
246:     } else {
247:       // The front is identical. Instead of dropping it, let's aggregate the back!
248:       const existing = byFront.get(key)!;
249:       if (jaccardSimilarity(existing.back, card.back) < 0.65) {
250:         // Format as a bulleted list if we are combining multiple answers
251:         if (!existing.back.startsWith("• ")) {
252:           existing.back = "• " + existing.back;
253:         }
254:         existing.back += "\n• " + card.back;
255:       }
256:     }
257:   }
258:   const unique = Array.from(byFront.values());
259: 
260:   // Step 2: Jaccard dedup on backs — O(n²) but n is small (≤ 70)
261:   const kept: RawCard[] = [];
262:   for (const card of unique) {
263:     let isDuplicate = false;
264:     for (const existing of kept) {
265:       if (jaccardSimilarity(card.back, existing.back) > 0.65) {
266:         // Keep the one with the shorter (more concise) back
267:         if (card.back.length < existing.back.length) {
268:           kept.splice(kept.indexOf(existing), 1, card);
269:         }
270:         isDuplicate = true;
271:         break;
272:       }
273:     }
274:     if (!isDuplicate) kept.push(card);
275:   }
276:   return kept;
277: }
