279: // ─── Per-Card Quality Scoring ─────────────────────────────────────────────────
280: // Every generated card gets a score 0-10. Cards are sorted descending before
281: // the cap is applied, so only the highest-quality cards surface.
282: 
283: /** Filler phrases that, if present in a back, reduce quality */
284: const FILLER_BACK_PHRASES = [
285:   /\bit is important to note\b/i,
286:   /\bin this (?:lesson|chapter|module|unit|context|section)\b/i,
287:   /\bas we have seen\b/i,
288:   /\bthe following\b/i,
289:   /\bwe will (?:discuss|explore|examine|look at|learn)\b/i,
290:   /\bplease (?:note|refer|see|read)\b/i,
291:   /\bfor (?:more|further) (?:information|details?)\b/i,
292: ];
293: 
294: function scoreCard(card: RawCard): number {
295:   let score = 5; // neutral baseline
296: 
297:   // +2: front is a proper question (5W1H) or recognized imperative prompt
298:   if (/^(what|how|why|when|where|who)\b/i.test(card.front.trim())) score += 2;
299:   else if (/^(define|explain|describe|identify|discuss|compare|summarize|give|in simple|provide|elaborate|state|complete|briefly|outline)\b/i.test(card.front.trim())) score += 2;
300: 
301:   // +2: back is concise (≤ 100 chars)
302:   if (card.back.length <= 100) score += 2;
303:   else if (card.back.length <= 160) score += 1;
304: 
305:   // +1: back contains a definition verb (high signal)
306:   if (/\b(is defined as|refers to|is known as|means|stands for|is characterized by)\b/i.test(card.back))
307:     score += 1;
308: 
309:   // +1: card has a hint
310:   if (card.hint && card.hint.trim().length > 5) score += 1;
311: 
312:   // −2: front contains meta words
313:   if (/\b(note|objective|activity|task|summary|review|agenda|outline)\b/i.test(card.front))
314:     score -= 2;
315: 
316:   // −2: back contains filler phrases
317:   if (FILLER_BACK_PHRASES.some(rx => rx.test(card.back))) score -= 2;
318: 
319:   // −1: back is very long (likely a paragraph dump)
320:   if (card.back.length > 300) score -= 1;
321: 
322:   // −3: front does NOT end with a question mark, period, or ellipsis (should be a question or imperative prompt)
323:   const f = card.front.trim();
324:   if (!f.endsWith("?") && !f.endsWith(".") && !f.endsWith("...")) score -= 3;
325: 
326:   return score;
327: }
