341: // ─── Definition Pattern Registry (Fix 3 — Enhanced) ─────────────────────────
342: 
343: interface DefinitionPattern {
344:   regex: RegExp;
345:   subjectGroup: number;
346:   predicateGroup: number;
347: }
348: 
349: /**
350:  * Eight regex patterns that extract (subject, predicate) pairs from
351:  * definition-style sentences. Checked in order — first match wins.
352:  */
353: const DEFINITION_PATTERNS: DefinitionPattern[] = [
354:   // 1a. Strong definition verbs
355:   {
356:     regex:
357:       /^(.+?)\s+(?:is defined as|refers to|is known as|means|stands for)\s+(.+)$/i,
358:     subjectGroup: 1,
359:     predicateGroup: 2,
360:   },
361:   // 1b. Generic verbs (is, are, was, were) - stricter match
362:   {
363:     regex:
364:       /^([A-Z][a-zA-Z0-9\s\-]{2,35})\s+(?:is|are|was|were)\s+(.+)$/,
365:     subjectGroup: 1,
366:     predicateGroup: 2,
367:   },
368:   // 2. "X can be defined/described as Y"
369:   {
370:     regex: /^(.+?)\s+can be (?:defined|described) as\s+(.+)$/i,
371:     subjectGroup: 1,
372:     predicateGroup: 2,
373:   },
374:   // 3. "X involves/consists of/comprises/includes/encompasses Y"
375:   {
376:     regex:
377:       /^(.+?)\s+(?:involves?|consists? of|comprises?|includes?|encompasses?)\s+(.+)$/i,
378:     subjectGroup: 1,
379:     predicateGroup: 2,
380:   },
381:   // 4. "The term/concept/idea/principle of X is/refers to/means Y"
382:   {
383:     regex:
384:       /^(?:the (?:term|concept|idea|principle) (?:of )?)\s*(.+?)\s+(?:is|refers to|means)\s+(.+)$/i,
385:     subjectGroup: 1,
386:     predicateGroup: 2,
387:   },
388:   // 5. "X was developed/invented/created/founded/introduced/proposed/discovered by Y"
389:   {
390:     regex:
391:       /^(.+?)\s+was (?:developed|invented|created|founded|introduced|proposed|discovered) by\s+(.+)$/i,
392:     subjectGroup: 1,
393:     predicateGroup: 2,
394:   },
395:   // 6. "X is characterized/distinguished/marked by Y"
396:   {
397:     regex:
398:       /^(.+?)\s+(?:is characterized|is distinguished|is marked) by\s+(.+)$/i,
399:     subjectGroup: 1,
400:     predicateGroup: 2,
401:   },
402:   // 7. "X occurs/happens/takes place when/during/in Y"
403:   {
404:     regex:
405:       /^(.+?)\s+(?:occurs?|happens?|takes? place) (?:when|during|in)\s+(.+)$/i,
406:     subjectGroup: 1,
407:     predicateGroup: 2,
408:   },
409:   // 8. "X represents/symbolizes/signifies/denotes Y"
410:   {
411:     regex:
412:       /^(.+?)\s+(?:represents?|symbolizes?|signifies?|denotes?)\s+(.+)$/i,
413:     subjectGroup: 1,
414:     predicateGroup: 2,
415:   },
416: ];
