418: // ─── Subject Cleaning Utilities ─────────────────────────────────────────────
419: 
420: /** Regex to reject pronoun/demonstrative/vague subjects that make nonsensical questions */
421: const JUNK_SUBJECT_REGEX =
422:   /^(this|that|it|its|they|these|those|he|she|we|you|our|their|some|many|all|few|most|both|each|every|any|other|another|such|more|several|here|there|the|a|an|sample|sample content|content|template)(\b|$)/i;
423: 
424: /**
425:  * Check if a subject is too vague/junk to make a good flashcard question.
426:  * Returns true if the subject should be rejected.
427:  */
428: function isJunkSubject(subject: string): boolean {
429:   const s = subject.trim();
430:   // Too short or too long
431:   if (s.length < 3 || s.length > 60) return true;
432:   // Just punctuation or numbers
433:   if (/^[\d\s.,:;\-!?()]+$/.test(s)) return true;
434:   // Contains an internal period (like "academic integrity. Academic dishonesty")
435:   if (/\w\.\s+[A-Z]/.test(s)) return true;
436:   // Contains multiple commas (like "family, sickness, or accident, written")
437:   if ((s.match(/,/g) || []).length >= 2) return true;
438:   // Ends with a trailing adjective, verb, or preposition
439:   if (/\b(written|given|taken|made|said|done|or|and|with|by|for|to|in|of|at)$/i.test(s)) return true;
440:   // Starts with a pronoun/demonstrative or junk word
441:   if (JUNK_SUBJECT_REGEX.test(s)) return true;
442:   // Generic meta terms
443:   if (/^(sample|content|sample content|topic|lesson|unit|chapter|section|part)\b/i.test(s)) return true;
444:   // Ends with a period and is very short (fragment like "These.")
445:   if (s.endsWith(".") && s.length < 10) return true;
446:   // Just a pronoun + common noun (e.g. "These tools", "This method", "Those items")
447:   if (/^(this|that|these|those|the|some|such)\s+\w+\.?$/i.test(s)) return true;
448:   return false;
449: }
450: 
451: /**
452:  * Clean a slide title or subject by stripping leading numbering, list markers,
453:  * "(Part N)" tags, and trailing punctuation to make it look natural in a question.
454:  */
455: function cleanSubject(text: string): string {
456:   return text
457:     // Strip leading list markers: "1. ", "A)", "ii.", "2.Printer" (even without space)
458:     .replace(/^(?:\d+|[a-zA-Z]|[ivxlIVXL]+)[.)\-:\]]\s*/, "")
459:     // Strip leading special characters/bullets (•, -, *, >, etc)
460:     .replace(/^[\u2022\u2023\u25E6\u2043\u2219*\-=>~]\s*/, "")
461:     // Strip "Part N", "continued", etc.
462:     .replace(/\s*\((?:part|pt\.?)\s*\d+\)/gi, "")
463:     .replace(/\s*\(continued\)/gi, "")
464:     .replace(/\s*\(cont['']?d?\.?\)/gi, "")
465:     .replace(/\s*[-–—]\s*(?:part|pt\.?)\s*\d+$/gi, "")
466:     // Strip trailing numbers that look like slide counts (e.g. "Title 1")
467:     .replace(/\s+\d+\s*$/, "")
468:     // Strip trailing punctuation
469:     .replace(/[.,:;!]+$/, "")
470:     .trim();
471: }
