473: // ─── Ordered List Detection (Fix 4 — Enhanced) ──────────────────────────────
474: 
475: /** Matches numbered (1.), lettered (a.), and roman numeral (i.) list items */
476: const STEP_REGEX =
477:   /^(?:\d+[.\)]\s+|[a-zA-Z][.\)]\s+|[ivxlIVXL]+[.\)]\s+)(.{10,})/;
478: 
479: /**
480:  * Scans for consecutive ordered-list lines, groups them under the nearest
481:  * header, and produces summary + individual step cards.
482:  */
483: function detectOrderedLists(lines: string[], usedLines: Set<number>): RawCard[] {
484:   const cards: RawCard[] = [];
485:   let i = 0;
486: 
487:   while (i < lines.length) {
488:     if (usedLines.has(i)) {
489:       i++;
490:       continue; // ← Bug fix: skip to next iteration instead of falling through to stepStart = i
491:     }
492: 
493:     const stepStart = i;
494:     const steps: string[] = [];
495:     const matchedIndices: number[] = [];
496: 
497:     // Collect consecutive step lines
498:     while (i < lines.length) {
499:       if (usedLines.has(i)) break;
500:       const match = lines[i].match(STEP_REGEX);
501:       if (match) {
502:         steps.push(match[1].trim());
503:         matchedIndices.push(i);
504:         i++;
505:       } else {
506:         break;
507:       }
508:     }
509: 
510:     if (steps.length >= 2) {
511:       // Mark lines as used
512:       matchedIndices.forEach(idx => usedLines.add(idx));
513: 
514:       // Look back for a header to give context to the ordered list
515:       let header = "";
516:       if (stepStart > 0) {
517:         const prevLine = lines[stepStart - 1];
518:         if (
519:           prevLine.length > 3 &&
520:           prevLine.length < 80 &&
521:           !/[.?!]$/.test(prevLine)
522:         ) {
523:           header = cleanSubject(prevLine);
524:         }
525:       }
526: 
527:       // If we couldn't find a meaningful header, these flashcards will lack context
528:       // (e.g., "What are the steps of this process?"). Skip generating them.
529:       if (!header || isJunkSubject(header) || header.toLowerCase() === "this process") {
530:         continue;
531:       }
532: 
533:       // Summary card with arrow-separated steps (max 4)
534:       const summaryBack = steps.slice(0, 4).join(" → ");
535:       cards.push({
536:         front: `What are the steps of ${header}?`,
537:         back: summaryBack,
538:         hint: `There are ${steps.length} steps total.`,
539:       });
540: 
541:       // Individual step cards when 4+ steps
542:       if (steps.length >= 4) {
543:         steps.slice(0, 5).forEach((step, idx) => {
544:           cards.push({
545:             front: `What is step ${idx + 1} of ${header}?`,
546:             back: step,
547:           });
548:         });
549:       }
550:     } else {
551:       if (matchedIndices.length === 0) i++;
552:     }
553:   }
554: 
555:   return cards;
556: }
