558: // ─── PPTX Slide-Level XML Parser (Fix 1 — Enhanced) ─────────────────────────
559: // Now generates one card per bullet point (not just the first), plus a
560: // summary card for slides with 3+ bullets. Uses content-aware question types.
561: 
562: /**
563:  * Extract a meaningful subject from bullet text for better question generation.
564:  * Tries definition patterns and colon-splits before falling back to slide title.
565:  * Returns null if no quality subject can be derived.
566:  */
567: function extractBulletSubject(bulletText: string, slideTitle: string): { subject: string; isDefinition: boolean } | null {
568:   // 1. Check for "Term: definition" pattern (ignoring leading markers)
569:   const cleanBullet = bulletText.replace(/^(?:\d+|[a-zA-Z]|[ivxlIVXL]+)[.)\-:\]]\s*/, "").trim();
570:   const colonMatch = cleanBullet.match(/^([A-Z][a-zA-Z0-9\s\-]{2,40})\s*[:–—]\s*(.+)$/i);
571:   if (colonMatch) {
572:     const term = cleanSubject(colonMatch[1]);
573:     if (!isJunkSubject(term)) {
574:       return { subject: term, isDefinition: true };
575:     }
576:   }
577: 
578:   // 2. Check for "X is/are/refers to Y" definition patterns
579:   for (const pattern of DEFINITION_PATTERNS) {
580:     const match = cleanBullet.match(pattern.regex);
581:     if (match) {
582:       const subject = cleanSubject(match[pattern.subjectGroup]?.trim() ?? "");
583:       if (!isJunkSubject(subject)) {
584:         return { subject, isDefinition: true };
585:       }
586:     }
587:   }
588: 
589:   // 3. Try to extract a leading noun phrase (first capitalized segment before a verb)
590:   const nounPhraseMatch = cleanBullet.match(/^([A-Z][a-zA-Z0-9\s\-]{3,35})(?:\s+(?:is|are|was|were|can|has|have|helps?|allows?|enables?|provides?|involves?)\b)/i);
591:   if (nounPhraseMatch) {
592:     const np = cleanSubject(nounPhraseMatch[1]);
593:     if (!isJunkSubject(np)) {
594:       return { subject: np, isDefinition: false };
595:     }
596:   }
597: 
598:   // 4. Fallback: use the cleaned slide title
599:   const cleanedTitle = cleanSubject(slideTitle);
600:   if (!isJunkSubject(cleanedTitle)) {
601:     return { subject: cleanedTitle, isDefinition: false };
602:   }
603: 
604:   // 5. No quality subject found — skip this bullet
605:   return null;
606: }
