608: function parsePptxSlides(
609:   buffer: Buffer,
610:   allowedSlides?: Set<number> // 1-indexed slide numbers; undefined = all slides
611: ): RawCard[] {
612:   const cards: RawCard[] = [];
613:   const zip = new AdmZip(buffer);
614:   const entries = zip.getEntries();
615: 
616:   // Filter only slide XML files (skip slideLayouts, slideMasters, etc.)
617:   const slideEntries = entries
618:     .filter((e) => /^ppt\/slides\/slide\d+\.xml$/i.test(e.entryName))
619:     .sort((a, b) => {
620:       const numA = parseInt(
621:         a.entryName.match(/slide(\d+)/i)?.[1] ?? "0",
622:         10
623:       );
624:       const numB = parseInt(
625:         b.entryName.match(/slide(\d+)/i)?.[1] ?? "0",
626:         10
627:       );
628:       return numA - numB;
629:     });
630: 
631:   for (const entry of slideEntries) {
632:     // ── Slide-selection filter (Vaia-style page picker) ──
633:     const slideNumber = parseInt(
634:       entry.entryName.match(/slide(\d+)/i)?.[1] ?? "0",
635:       10
636:     );
637:     if (allowedSlides && !allowedSlides.has(slideNumber)) continue;
638: 
639:     const xml = entry.getData().toString("utf8");
640: 
641:     // Extract title text: look for <p:ph type="title" /> or <p:ph type="ctrTitle" />
642:     // then grab all <a:t> text within that shape
643:     let titleText = "";
644:     let bodyText = "";
645: 
646:     // Split XML into shape blocks <p:sp>...</p:sp>
647:     const shapeBlocks =
648:       xml.match(/<p:sp\b[^>]*>[\s\S]*?<\/p:sp>/gi) || [];
649: 
650:     for (const shape of shapeBlocks) {
651:       const isTitle = /<p:ph[^>]*type\s*=\s*"(title|ctrTitle)"/i.test(
652:         shape
653:       );
654:       const isSubTitle = /<p:ph[^>]*type\s*=\s*"subTitle"/i.test(shape);
655: 
656:       // Extract all <a:t>...</a:t> text nodes from this shape
657:       const textNodes = shape.match(/<a:t>([^<]*)<\/a:t>/gi) || [];
658:       const shapeText = textNodes
659:         .map((t) => t.replace(/<\/?a:t>/gi, ""))
660:         .join(" ")
661:         .trim();
662: 
663:       if (!shapeText) continue;
664: 
665:       if (isTitle) {
666:         titleText += (titleText ? " " : "") + shapeText;
667:       } else if (isSubTitle) {
668:         bodyText += (bodyText ? "\n" : "") + shapeText;
669:       } else {
670:         bodyText += (bodyText ? "\n" : "") + shapeText;
671:       }
672:     }
673: 
674:     if (!titleText && bodyText) {
675:       const parts = bodyText.split("\n");
676:       titleText = parts[0].trim();
677:       bodyText = parts.slice(1).join("\n").trim();
678:     }
679: 
680:     titleText = titleText.replace(/:$/, "").trim();
681:     bodyText = bodyText.trim();
682: 
683:     // Ignore generic non-educational slides (expanded blocklist)
684:     const rawCleanTitle = titleText.replace(/[^a-zA-Z0-9\s]/g, "").trim().toLowerCase();
685:     if (
686:       IGNORE_TITLES.includes(rawCleanTitle) ||
687:       IGNORE_PREFIXES.some((p) => rawCleanTitle.startsWith(p))
688:     ) {
689:       continue;
690:     }
691: 
692:     // Split body into individual bullet/body points, filtering out junk
693:     const bodyPoints = bodyText
694:       .split("\n")
695:       .map((p) => p.trim())
696:       .filter((p) => {
697:         // Too short: must be at least 2 words OR a capitalised single term ≥ 5 chars
698:         const wordCount = p.split(/\s+/).filter(Boolean).length;
699:         if (wordCount < 2 && p.length < 5) return false;
700:         if (p.length < 4) return false;
701:         // Non-educational lines (attributions, names, etc.)
702:         if (NON_EDUCATIONAL_LINE_REGEX.test(p)) return false;
703:         // Looks like a person's name
704:         if (looksLikePersonName(p)) return false;
705:         // Meta/instructional and policy sentences
706:         if (META_SENTENCE_START_REGEX.test(p) || POLICY_SENTENCE_REGEX.test(p)) return false;
707:         return true;
708:       });
709: 
710:     if (!titleText || bodyPoints.length === 0) continue;
711: 
712:     // ── Generate one card per bullet with content-aware questions ──
713:     for (const point of bodyPoints) {
714:       // Fast-path: "Term: Definition" or "Term — Definition" bullet
715:       // → generate "What is Term?" / "Term" answer directly
716:       const cleanPoint = point.replace(/^(?:\d+|[a-zA-Z]|[ivxlIVXL]+)[.)\-:\]]\s*/, "").trim();
717:       const termDefMatch = cleanPoint.match(
718:         /^([A-Z][a-zA-Z0-9\s\-]{1,35})\s*(?:[:–—]|-{2})\s*(.{10,})$/
719:       );
720:       if (termDefMatch) {
721:         const term = cleanSubject(termDefMatch[1]);
722:         const definition = termDefMatch[2].replace(/\.+$/, "").trim();
723:         if (!isJunkSubject(term) && definition.length >= 10) {
724:           cards.push({
725:             front: `What is ${term}?`,
726:             back: definition,
727:           });
728:           continue;
729:         }
730:       }
731: 
732:       const extracted = extractBulletSubject(point, titleText);
733:       // Skip bullets where no quality subject could be derived
734:       if (!extracted) continue;
735:       const { subject, isDefinition } = extracted;
736:       cards.push({
737:         front: generateQuestion(subject, point, isDefinition),
738:         back: point,
739:       });
740:     }
741: 
742:   }
743: 
744:   // Sort by quality score descending, apply dynamic cap, then dedup
745:   const cap = getPptxCardCap(slideEntries.length);
746:   return deduplicateCards(
747:     cards.sort((a, b) => scoreCard(b) - scoreCard(a))
748:   ).slice(0, cap);
749: }
