751: // ─── Text → Flashcard Extraction (Enhanced Rule-Based NLP) ───────────────────
752: // Integrates: Fix 2 (varied questions), Fix 3 (expanded definitions),
753: // Fix 4 (ordered lists), Bonus (enumeration detection).
754: 
755: function processParagraph(paragraph: string, header: string, cards: RawCard[]) {
756:   const doc = nlp(paragraph);
757:   const sentences = doc.sentences().out("array") as string[];
758:   let matchedAny = false;
759: 
760:   for (let sIdx = 0; sIdx < sentences.length; sIdx++) {
761:     const sentence = sentences[sIdx];
762:     if (sentence.length < 20 || sentence.length > 250) continue;
763:     if (META_SENTENCE_START_REGEX.test(sentence.trim()) || POLICY_SENTENCE_REGEX.test(sentence)) continue;
764: 
765:     // A. Explicit Glossary / Definition Pattern
766:     // Strip leading list markers (e.g. "1. ", "a) ") to allow glossary matching on numbered lists
767:     const cleanSentence = sentence.replace(/^(?:\d+(?:\.\d+)*|[a-zA-Z]|[ivxlIVXL]+)[.)\-:\]]\s*/, "").trim();
768:     const glossaryMatch = cleanSentence.match(/^([A-Z][a-zA-Z0-9\s\-]{2,30})\s*(:| - |—)\s*(.+)$/i);
769:     if (glossaryMatch) {
770:       const term = cleanSubject(glossaryMatch[1]);
771:       const definition = glossaryMatch[3].replace(/\.$/, "").trim();
772:       if (!isJunkSubject(term) && definition.length > 5 && !META_HEADER_REGEX.test(term.replace(/[^a-zA-Z0-9\s]/g, "").trim())) {
773:         cards.push({ front: generateQuestion(term, definition, true), back: definition });
774:         matchedAny = true;
775:         continue;
776:       }
777:     }
778: 
779:     // B. Question & Answer Detection
780:     if (sentence.trim().endsWith("?")) {
781:       if (sIdx < sentences.length - 1) {
782:         const nextSentence = sentences[sIdx + 1];
783:         const isInstruction = /^(?:(?:\d+(?:\.\d+)*|[a-zA-Z]|[ivxlIVXL]+)[.)]\s*)?(?:mention|describe|explain|list|identify|discuss|compare|what|how|why)\b/i.test(nextSentence.trim());
784:         const isBullet = /^(?:(?:\d+(?:\.\d+)*|[a-zA-Z]|[ivxlIVXL]+)[.)]\s*)/.test(nextSentence.trim());
785:         
786:         if (!nextSentence.trim().endsWith("?") && nextSentence.length > 15 && nextSentence.length < 150 && !/^(this|that|it|they|these|those|he|she)\b/i.test(nextSentence.trim()) && !isInstruction && !isBullet) {
787:           cards.push({ front: sentence.trim(), back: nextSentence.trim() });
788:           matchedAny = true;
789:           continue;
790:         }
791:       }
792:     }
793: 
794:     // C. Enumeration Detection
795:     const enumMatch = sentence.match(/(?:there are|there exist|includes?|consists? of)\s+(?:(\w+)\s+)?(?:types?|kinds?|forms?|categories|parts?|components?|elements?|stages?|steps?|phases?|levels?)\s+(?:of\s+)?(.+?)(?::|,\s*namely|,\s*such as|,\s*including)\s*(.+)$/i);
796:     if (enumMatch) {
797:       const enumSubject = enumMatch[2]?.trim();
798:       const enumItems = enumMatch[3]?.replace(/\.$/, "").trim();
799:       if (enumSubject && enumItems && enumSubject.length > 2 && enumItems.length > 5) {
800:         cards.push({
801:           front: `What are the types of ${enumSubject}?`,
802:           back: enumItems,
803:           hint: enumMatch[1] ? `There are ${enumMatch[1]} of them.` : undefined,
804:         });
805:         matchedAny = true;
806:         continue;
807:       }
808:     }
809: 
810:     // D. Expanded Definition Triggers
811:     if (sentence.includes("?")) continue;
812:     let defMatched = false;
813:     for (const pattern of DEFINITION_PATTERNS) {
814:       const match = sentence.match(pattern.regex);
815:       if (!match) continue;
816:       let subject = match[pattern.subjectGroup]?.trim() ?? "";
817:       const predicate = match[pattern.predicateGroup]?.replace(/\.$/, "").trim() ?? "";
818:       // Clean pronouns and apply our global subject cleaner (strips numbering/bullets)
819:       subject = subject.replace(/^(this|that|these|those)\s+/i, "").replace(/\s+(this|that|it|they)$/i, "").trim();
820:       subject = cleanSubject(subject);
821:       
822:       if (isJunkSubject(subject) || subject.includes("?")) break;
823:       if (subject.length > 2 && subject.length < 50 && predicate.length > 10) {
824:         cards.push({ front: generateQuestion(subject, predicate, true), back: predicate });
825:         defMatched = true;
826:         matchedAny = true;
827:         break;
828:       }
829:     }
830:     if (defMatched) continue;
831:   }
832: 
833:   // E. Narrative Fallback
834:   // If no specific definitions or lists were found in this paragraph,
835:   // and it has MULTIPLE proper sentences (proving it's a real narrative, not a glued list of bullets),
836:   // create a summary card so we don't lose the historical/contextual information.
837:   if (!matchedAny && header && !isJunkSubject(header) && header.length > 3) {
838:     if (sentences.length >= 2 && paragraph.length >= 100 && paragraph.length <= 600) {
839:       cards.push({
840:         front: `Summarize the key points of ${cleanSubject(header)}.`,
841:         back: paragraph,
842:       });
843:       matchedAny = true;
844:     }
845:   }
846: }
