848: function extractFlashcardsFromText(text: string): RawCard[] {
849:   const cards: RawCard[] = [];
850:   const lines = text
851:     .split("\n")
852:     .map((l) => l.trim())
853:     .filter(Boolean)
854:     .filter((l) => {
855:       // Strip standalone page numbers often found at the bottom of PDF slides
856:       if (/^\d+$/.test(l)) return false;
857:       // Strip common footers like "Prepared by: Name" or "Presented by: Name"
858:       if (/^(?:prepared|presented)\s+by\s*[:\w\s.,]*$/i.test(l)) return false;
859:       return true;
860:     });
861:   const usedLines = new Set<number>();
862: 
863:   // 1. Detect ordered/numbered/lettered/roman lists
864:   const orderedListCards = detectOrderedLists(lines, usedLines);
865:   cards.push(...orderedListCards);
866: 
867:   // 2. Block-Based Structural Parsing
868:   let currentHeader = "";
869:   let paragraphBuffer = "";
870: 
871:   const flushParagraph = () => {
872:     if (paragraphBuffer) {
873:       let cleanPara = paragraphBuffer.replace(/([^.?!])\n+/g, "$1 ").replace(/\n+/g, " ");
874:       cleanPara = cleanPara.replace(/\s+/g, " ").trim();
875:       processParagraph(cleanPara, currentHeader, cards);
876:       paragraphBuffer = "";
877:     }
878:   };
879: 
880:   for (let i = 0; i < lines.length; i++) {
881:     if (usedLines.has(i)) {
882:       flushParagraph();
883:       continue;
884:     }
885: 
886:     const line = lines[i];
887: 
888:     // Detect Bullet Points attached to the current header FIRST
889:     const bulletMatch = line.match(/^[\u2022\u2023\u25E6\u2043\-\*]\s+(.+)/);
890:     if (bulletMatch) {
891:       flushParagraph();
892:       const definition = bulletMatch[1].trim();
893:       if (definition.length > 5 && currentHeader) {
894:         cards.push({
895:           front: generateQuestion(cleanSubject(currentHeader), definition),
896:           back: definition,
897:         });
898:       }
899:       continue;
900:     }
901: 
902:     // Detect standalone Headers (strict heuristic to avoid wrapped lines)
903:     let isHeader = false;
904:     if (line.length > 3 && line.length <= 60 && !/[.?!;,]$/.test(line)) {
905:       const words = line.split(" ");
906:       const titleCaseWords = words.filter((w) => /^[A-Z]/.test(w));
907:       // A header must be mostly title case (>= 50%) and not start with a lowercase letter
908:       if (
909:         (titleCaseWords.length / words.length >= 0.5) &&
910:         !/^[a-z]/.test(line) &&
911:         !/\b(include|are|is|the|a|an|and|or|of|to|in|with|for|by|on|as|at|from)$/i.test(line)
912:       ) {
913:         isHeader = true;
914:       }
915:     }
916: 
917:     if (isHeader) {
918:       flushParagraph();
919:       const rawClean = line.replace(/[^a-zA-Z0-9\s]/g, "").trim().toLowerCase();
920:       
921:       // Check if this header should be completely ignored (e.g. "Course Policies")
922:       const isIgnored = IGNORE_TITLES.includes(rawClean) || IGNORE_PREFIXES.some(p => rawClean.startsWith(p));
923:       
924:       if (isIgnored) {
925:         currentHeader = "__IGNORE__";
926:       } else if (!META_HEADER_REGEX.test(rawClean)) {
927:         currentHeader = line
928:           .replace(/^(?:\d+(?:\.\d+)*[.)]\s+|[a-zA-Z][.)]\s+|[ivxlIVXL]+[.)]\s+)/, "")
929:           .replace(/:$/, "")
930:           .trim(); // Strip leading enumerations and trailing colons
931:       }
932:       continue;
933:     }
934: 
935:     // Accumulate paragraph text if not ignored
936:     if (currentHeader !== "__IGNORE__") {
937:       // ── Smart Slide Fragment Detection for PDFs ──
938:       // If the line is short (like a slide bullet) and we have a header,
939:       // try to extract a flashcard directly from it instead of waiting for a full paragraph.
940:       
941:       // Look ahead/behind to see if the line is just a wrapped sentence, not a bullet.
942:       let isWrapped = false;
943:       
944:       const connectingWords = "and|or|but|so|for|nor|yet|the|a|an|this|that|these|those|some|any|of|in|to|with|on|at|from|by|about|as|into|like|through|after|over|between|out|against|during|without|before|under|around|among|is|are|was|were|be|been|being|have|has|had|do|does|did|can|could|shall|should|will|would|may|might|must|which|who|whom|whose|such as";
945:       
946:       const endsWithRegex = new RegExp(`\\b(${connectingWords})\\s*$`, "i");
947:       const startsWithRegex = new RegExp(`^\\s*(${connectingWords})\\b`, "i");
948: 
949:       // 1. Line ends with a connecting word (meaning it continues to the next line)
950:       if (endsWithRegex.test(line)) {
951:         isWrapped = true;
952:       } 
953:       // 2. Line starts with a lowercase letter or connecting word (meaning it's continuing the previous line)
954:       else if (/^[a-z]/.test(line) || startsWithRegex.test(line)) {
955:         isWrapped = true;
956:       }
957:       // 3. Next line starts with a lowercase letter or connecting word
958:       else if (i + 1 < lines.length) {
959:         const nextLine = lines[i + 1];
960:         if (/^[a-z]/.test(nextLine) || startsWithRegex.test(nextLine)) {
961:           isWrapped = true;
962:         }
963:       }
964: 
965:       if (!isWrapped && line.length >= 10 && line.length <= 150 && !/[.!?]$/.test(line)) {
966:         flushParagraph();
967:         const extracted = extractBulletSubject(line, currentHeader || "the topic");
968:         if (extracted && extracted.subject !== "the topic") {
969:           cards.push({
970:             front: generateQuestion(extracted.subject, line, extracted.isDefinition),
971:             back: line,
972:           });
973:         }
974:         continue;
975:       }
976: 
977:       paragraphBuffer += (paragraphBuffer ? " " : "") + line;
978:     }
979:   }
980:   flushParagraph();
981: 
982:   // Sort by quality score, deduplicate, apply dynamic cap
983:   const cap = getCardCap(text);
984:   return deduplicateCards(
985:     cards.sort((a, b) => scoreCard(b) - scoreCard(a))
986:   ).slice(0, cap);
987: }
