989: /** Filler openers that add zero information to a flashcard back. */
990: const FILLER_OPENER_REGEX =
991:   /^(?:it is (?:important to note|worth noting) that\s*|in this (?:lesson|chapter|module|unit|context|section)[,.]?\s*|as we (?:have seen|discussed|learned)[,.]?\s*|this (?:refers to|is defined as|means that)\s*|the concept (?:of\s+\w+\s+)?refers to\s*|basically[,.]?\s*|essentially[,.]?\s*|simply put[,.]?\s*|in other words[,.]?\s*)/i;
992: 
993: // ─── Answer Shortener (Flashcard Best Practice) ─────────────────────────────
994: // Flashcard backs should be concise but complete — don't chop mid-thought.
995: 
996: function shortenAnswer(text: string): string {
997:   // ── 0. Strip filler openers before length check ──
998:   let cleaned = text.replace(FILLER_OPENER_REGEX, "").trim();
999:   // Capitalise first char after stripping
1000:   if (cleaned.length > 0) cleaned = cleaned[0].toUpperCase() + cleaned.slice(1);
1001: 
1002:   // Already concise — leave it intact
1003:   if (cleaned.length <= 120) return cleaned;
1004: 
1005:   // ── 1. Try splitting on sentence-ending punctuation (best quality cut) ──
1006:   const sentenceMatch = cleaned.match(/^(.+?[.!?])(?:\s|$)/);
1007:   if (sentenceMatch) {
1008:     const firstSentence = sentenceMatch[1].trim();
1009:     if (firstSentence.length >= 15 && firstSentence.length <= 180) {
1010:       return firstSentence.replace(/\.+$/, "").trim();
1011:     }
1012:     // First sentence is very long — truncate at a word boundary
1013:     if (firstSentence.length > 180) {
1014:       const truncated = firstSentence.slice(0, 160);
1015:       const lastSpace = truncated.lastIndexOf(" ");
1016:       return (lastSpace > 40 ? truncated.slice(0, lastSpace) : truncated)
1017:         .replace(/[,;:\-]+$/, "")
1018:         .trim();
1019:     }
1020:   }
1021: 
1022:   // ── 2. No punctuation (PPTX bullet text) — detect clause boundaries ──
1023:   // When bullet points get concatenated, clause boundaries appear where a
1024:   // lowercase char is followed by a new Uppercase-starting word:
1025:   //   "...prototyping and iteration Prioritizes working software..."
1026:   //                                ^── clause boundary here
1027:   const clauseMatch = cleaned.match(/^(.{20,}?)(?<=[a-z,])\s+(?=[A-Z][a-z])/);
1028:   if (clauseMatch && clauseMatch[1].length >= 20 && clauseMatch[1].length <= 160) {
1029:     return clauseMatch[1].replace(/[,;:\-]+$/, "").trim();
1030:   }
1031: 
1032:   // ── 3. Fallback: hard truncate at word boundary ──
1033:   const truncated = cleaned.slice(0, 180);
1034:   const lastSpace = truncated.lastIndexOf(" ");
1035:   return (lastSpace > 40 ? truncated.slice(0, lastSpace) : truncated)
1036:     .replace(/[,;:\-]+$/, "")
1037:     .trim();
1038: }
