1040: // ─── PDF Kerning Fix ─────────────────────────────────────────────────────────
1041: // PDF and PPTX extractors often split words at glyph boundaries, producing
1042: // artifacts like "Sof tware", "f ocused", "decision- making". This function
1043: // detects and rejoins them.
1044: 
1045: /** Common 2–4 letter English words. If the left fragment IS one of these, we
1046:  *  keep the space (it's a real word boundary, not a kerning split). */
1047: const COMMON_SHORT_WORDS = new Set([
1048:   // ── 2-letter ──
1049:   'am','an','as','at','be','by','do','go','he','if','in','is','it','me','my',
1050:   'no','of','on','or','so','to','up','us','we',
1051:   // ── 3-letter ──
1052:   'act','add','age','ago','aid','aim','air','all','and','any','are','arm','art',
1053:   'ask','bad','bag','ban','bar','bat','bed','bet','big','bit','box','boy','bug',
1054:   'bus','but','buy','cab','can','cap','car','cat','cop','cow','cry','cup','cut',
1055:   'dad','day','did','die','dig','dog','dot','dry','due','ear','eat','egg','end',
1056:   'era','eye','fan','far','fat','fed','fee','few','fit','fix','fly','fog','for',
