1151: /**
1152:  * Fix common PDF/PPTX text-extraction kerning artifacts.
1153:  *
1154:  * Handles three classes of broken text:
1155:  *  1. Hyphen-space  → "decision- making"  →  "decision-making"
1156:  *  2. Single-char   → "f ocused"          →  "focused"
1157:  *  3. Multi-char    → "Sof tware"         →  "Software"
1158:  */
1159: function fixPdfKerning(text: string): string {
1160:   // 1. Hyphen-space: "decision- making" → "decision-making"
1161:   //    Keep "real-world use" intact — only rejoin if the next word is NOT
1162:   //    a recognized standalone word.
1163:   let result = text;
1164:   result = result.replace(
1165:     /(\w)-\s+([a-zA-Z]+)/g,
1166:     (match, left: string, rightWord: string) => {
1167:       if (COMMON_SHORT_WORDS.has(rightWord.toLowerCase())) return match;
1168:       // NLP backup: check if the right word is a recognized word type
1169:       const doc = nlp(rightWord.toLowerCase());
1170:       if (isNlpRecognizedWord(doc)) return match;
1171:       return left + "-" + rightWord;
1172:     },
1173:   );
1174: 
1175:   // 2. Single-char splits (excluding "a"/"I" and possessives like "AI's")
1176:   //    The lookbehind prevents joining "s accuracy" when preceded by an apostrophe.
1177:   result = result.replace(
1178:     /(?<![''\u2019])\b([bcdefghjklmnopqrstuvwxyzBCDEFGHJKLMNOPQRSTUVWXYZ])\s+([a-z]{2,})\b/g,
1179:     (match, ch: string, rest: string) => {
1180:       // Safety: if the right side is a recognized word on its own, keep separate
1181:       if (COMMON_SHORT_WORDS.has(rest.toLowerCase())) return match;
1182:       const doc = nlp(rest.toLowerCase());
1183:       if (isNlpRecognizedWord(doc)) {
1184:         // Only join if the combined form is also a recognized word
1185:         const combinedDoc = nlp((ch + rest).toLowerCase());
1186:         if (isNlpRecognizedWord(combinedDoc)) return ch + rest;
1187:         return match;
1188:       }
1189:       return ch + rest;
1190:     },
1191:   );
1192: 
1193:   // 3. Multi-char splits: use NLP to validate BOTH fragments before joining.
1194:   //    Only join when NEITHER side is a recognized word (= kerning artifact).
1195:   //    e.g. "Sof tware" → neither is a word → join ✓
1196:   //         "serve different" → both are words → keep separate ✓
1197:   //         "model parameters" → "parameters" is #Plural → keep separate ✓
1198:   result = result.replace(
1199:     /\b([A-Za-z]{2,6})\s+([a-z]{2,})\b/g,
1200:     (match, left: string, right: string) => {
1201:       const leftLower = left.toLowerCase();
1202:       const rightLower = right.toLowerCase();
1203: 
1204:       // Fast path: check common word list
1205:       if (COMMON_SHORT_WORDS.has(leftLower) || COMMON_SHORT_WORDS.has(rightLower)) {
1206:         return match;
1207:       }
1208: 
1209:       // NLP check: is the left fragment a recognized word?
1210:       const leftDoc = nlp(leftLower);
1211:       if (isNlpRecognizedWord(leftDoc)) return match;
1212: 
1213:       // NLP check: is the right fragment a recognized word?
1214:       const rightDoc = nlp(rightLower);
1215:       if (isNlpRecognizedWord(rightDoc)) return match;
1216: 
1217:       // Neither side is a recognized word → likely a kerning artifact → join
1218:       return left + right;
1219:     },
1220:   );
1221: 
1222:   return result;
1223: }
1224: 
1225: /**
1226:  * Check if compromise NLP recognizes a word as a specific part of speech.
1227:  * Compromise defaults unknown words to generic Noun/Singular — we deliberately
1228:  * skip that check so unknown fragments like "Sof" or "tware" are NOT considered
1229:  * recognized. Only words with specific POS tags (Verb, Adjective, Plural, etc.)
1230:  * that compromise assigns from its lexicon are treated as "known".
1231:  */
1232: function isNlpRecognizedWord(doc: ReturnType<typeof nlp>): boolean {
1233:   return (
1234:     doc.has('#Verb') || doc.has('#Adjective') || doc.has('#Adverb') ||
1235:     doc.has('#Preposition') || doc.has('#Conjunction') || doc.has('#Determiner') ||
1236:     doc.has('#Pronoun') || doc.has('#Copula') || doc.has('#Modal') ||
1237:     doc.has('#QuestionWord') || doc.has('#Plural') || doc.has('#Uncountable') ||
1238:     doc.has('#Demonym') || doc.has('#Possessive')
1239:   );
1240: }
