1242: // ─── Format Sanitizer / Quality Filter / Auto-Hint (Fix 5) ──────────────────
1243: // Cleans formatting artifacts, drops broken cards, and auto-generates hints
1244: // for cards that don't already have one.
1245: 
1246: function sanitizeCards(cards: RawCard[]): RawCard[] {
1247:   return cards
1248:     .map((card) => {
1249:       let cleanFront = card.front
1250:         .replace(/^[\s•\-\*\u2022\u2023\u25E6\u2043\u2219]+/, "") // Strip leading bullets
1251:         .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F\uFFFD\u200B\u2028\u2029\uE000-\uF8FF]/g, "") // Remove control chars, unknown glyphs, zero-width spaces
1252:         .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
1253:         .replace(/&quot;/g, '"').replace(/&#39;/g, "'") // Decode HTML entities
1254:         .replace(/\s+/g, " ") // Normalize spaces
1255:         .trim();
1256: 
1257:       // Fix PDF/PPTX kerning artifacts ("Sof tware" → "Software", "decision- making" → "decision-making")
1258:       cleanFront = fixPdfKerning(cleanFront);
1259: 
1260:       // Strip weird trailing punctuation from the front (like colons before question marks)
1261:       cleanFront = cleanFront.replace(/:\?$/, "?").replace(/:$/, "");
1262: 
1263:       let cleanBack = card.back
1264:         .replace(/^[\s•\-\*\u2022\u2023\u25E6\u2043\u2219]+/, "")
1265:         .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F\uFFFD\u200B\u2028\u2029\uE000-\uF8FF]/g, "")
1266:         .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
1267:         .replace(/&quot;/g, '"').replace(/&#39;/g, "'")
1268:         .replace(/^(?:Note|Important|Remember|Notice)(?:\s+that)?[:\-]?\s*/i, "")
1269:         .replace(/\s+/g, " ")
1270:         .trim();
1271: 
1272:       // Fix PDF/PPTX kerning artifacts
1273:       cleanBack = fixPdfKerning(cleanBack);
1274: 
1275:       // Fix "Wall of Text" — shorten to concise flashcard-friendly length
1276:       cleanBack = shortenAnswer(cleanBack);
1277: 
1278:       return {
1279:         front: cleanFront,
1280:         back: cleanBack,
1281:         hint: undefined,
1282:       };
1283:     })
1284:     .filter((card) => {
1285:       // Drop cards with empty or too-short content (junk labels)
1286:       if (card.front.length < 10 || card.back.length < 10) return false;
1287:       // Drop cards where the back is just a parenthesized label (e.g. '(RAD MODEL)')
1288:       if (/^\(.*\)$|^\[.*\]$/.test(card.back.trim())) return false;
1289:       // Drop cards where front is excessively long (likely a paragraph, not a question)
1290:       if (card.front.length > 200) return false;
1291:       // Drop cards where back is excessively long (walls of text)
1292:       if (card.back.length > 500) return false;
1293:       // Drop cards that are just numbers or page markers
1294:       if (/^\d+$/.test(card.front) || /^page\s*\d+$/i.test(card.front))
1295:         return false;
1296:       // Drop cards that are just author/group attributions or closing remarks
1297:       if (
1298:         /^(by|prepared by|presented by|submitted by|group)\s+[a-z0-9\s]+$/i.test(
1299:           card.back
1300:         )
1301:       )
1302:         return false;
1303:       // Drop Bible verses, quotes, and closing remarks
1304:       const bibleRefRegex = /[1-3]?\s*(?:Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|Samuel|Kings|Chronicles|Ezra|Nehemiah|Esther|Job|Psalms?|Proverbs?|Ecclesiastes|Song|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi|Matthew|Mark|Luke|John|Acts|Romans|Corinthians|Galatians|Ephesians|Philippians|Colossians|Thessalonians|Timothy|Titus|Philemon|Hebrews|James|Peter|Jude|Revelation)\s+\d+[:\d\-,\s]*/i;
1305:       const bibleVersionRegex = /\b(NIV|KJV|NKJV|ESV|NLT|NASB|CSB|RSV|NRSV|ASV|MSG|AMP|CEV|GNT|TLB)\b/;
1306:       if (
1307:         bibleRefRegex.test(card.front) ||
1308:         bibleRefRegex.test(card.back) ||
1309:         bibleVersionRegex.test(card.front) ||
1310:         bibleVersionRegex.test(card.back) ||
1311:         /(thank you|god bless|any questions\?|questions\?)/i.test(card.front) ||
1312:         /(thank you|god bless|any questions\?|questions\?)/i.test(card.back) ||
1313:         /^(?:"|").+(?:"|")$/.test(card.back)
1314:       )
1315:         return false;
1316:       return true;
1317:     });
1318: }
