1384:               orderIndex: index,
1385:             })),
1386:           },
1387:         },
1388:       });
1389: 
1390:       return NextResponse.json(
1391:         { deckId: deck.id, saved: true },
1392:         { status: 201 }
1393:       );
1394:     }
1395: 
1396:     // ── Preview mode: parse the file and return the cards for editing ──
1397:     const enrollment = await db.enrollment.findUnique({
1398:       where: {
1399:         courseId_studentId: { courseId, studentId: session.user.id },
1400:       },
1401:     });
1402: 
1403:     if (!enrollment || enrollment.status !== "APPROVED") {
1404:       return NextResponse.json(
1405:         { message: "Not enrolled in this course" },
1406:         { status: 403 }
1407:       );
1408:     }
1409: 
1410:     const attachment = await db.attachment.findUnique({
1411:       where: { id: attachmentId },
1412:       include: { syllabusItem: true },
1413:     });
1414: 
1415:     if (!attachment || attachment.type !== "FILE") {
1416:       return NextResponse.json(
1417:         { message: "Attachment not found or is not a file" },
1418:         { status: 404 }
1419:       );
1420:     }
1421: 
1422:     // Fetch the file
1423:     let fileUrl = attachment.url;
1424:     if (fileUrl.startsWith("/")) {
1425:       const baseUrl = new URL(req.url).origin;
1426:       fileUrl = `${baseUrl}${fileUrl}`;
