1445:           Array.isArray(selectedSlides) && selectedSlides.length > 0
1446:             ? new Set(selectedSlides.map(Number))
1447:             : undefined;
1448:         generatedCards = parsePptxSlides(buffer, allowedSlides);
1449:       } else if (fileNameLower.endsWith(".pdf")) {
1450:         // ── PDF: Rule-based NLP text extraction with optional page filter ──
1451:         const arrayBuffer = await response.arrayBuffer();
1452:         const buffer = Buffer.from(arrayBuffer);
1453:         const pdfParse = require("pdf-parse/lib/pdf-parse.js");
1454: 
1455:         // Determine which pages to include:
