1457:         // 2. pageFrom/pageTo (legacy range) as fallback
1458:         // 3. All pages if neither is provided
1459:         const allowedPages: Set<number> | null =
1460:           Array.isArray(selectedPages) && selectedPages.length > 0
1461:             ? new Set(selectedPages.map(Number))
1462:             : null;
1463: 
1464:         const fromPage = !allowedPages && typeof pageFrom === "number" && pageFrom >= 1 ? pageFrom : 1;
1465:         const toPage = !allowedPages && typeof pageTo === "number" && pageTo >= fromPage ? pageTo : Infinity;
1466:         const isFiltered = allowedPages !== null || fromPage > 1 || toPage < Infinity;
1467: 
1468:         if (isFiltered) {
1469:           // Collect text only from allowed pages
1470:           const pageTexts: string[] = [];
1471:           await pdfParse(buffer, {
1472:             pagerender: (pageData: { pageIndex: number; getTextContent: () => Promise<{ items: { str: string }[] }> }) => {
1473:               const pageNum = pageData.pageIndex + 1; // pageIndex is 0-based
1474: 
1475:               // Check if this page is in the allowed set
1476:               if (allowedPages) {
1477:                 if (!allowedPages.has(pageNum)) return Promise.resolve("");
1478:               } else {
1479:                 if (pageNum < fromPage || pageNum > toPage) return Promise.resolve("");
1480:               }
1481: 
1482:               return pageData.getTextContent().then(
1483:                 (content: any) => {
1484:                   let lastY: number | undefined;
1485:                   let text = "";
1486:                   for (const item of content.items) {
1487:                     if (lastY === item.transform[5] || lastY === undefined) {
1488:                       text += item.str;
1489:                     } else {
1490:                       text += "\n" + item.str;
1491:                     }
1492:                     lastY = item.transform[5];
1493:                   }
1494:                   pageTexts.push(text);
1495:                   return text;
1496:                 }
1497:               );
1498:             },
1499:           });
1500:           generatedCards = extractFlashcardsFromText(pageTexts.join("\n"));
1501:         } else {
1502:           // No filter — original fast path
1503:           const pdfData = await pdfParse(buffer);
1504:           generatedCards = extractFlashcardsFromText(pdfData.text);
1505:         }
1506:       } else if (
1507:         fileNameLower.endsWith(".txt") ||
1508:         fileNameLower.endsWith(".csv")
1509:       ) {
1510:         const rawText = await response.text();
1511:         generatedCards = extractFlashcardsFromText(rawText);
1512:       } else if (fileNameLower.endsWith(".docx")) {
1513:         const arrayBuffer = await response.arrayBuffer();
1514:         const buffer = Buffer.from(arrayBuffer);
1515:         const officeparser = require("officeparser");
1516:         // Typed options object — avoids `as any` per strict-typing rule
1517:         interface OfficeParserOptions { fileType: string; }
1518:         const officeOptions: OfficeParserOptions = { fileType: "docx" };
1519:         const ast = await officeparser.parseOffice(buffer, officeOptions);
1520:         generatedCards = extractFlashcardsFromText(ast.toText());
1521:       } else {
1522:         return NextResponse.json(
1523:           {
1524:             message:
1525:               "Unsupported file type. Only .pdf, .pptx, .docx, and .txt files can be converted to flashcards.",
1526:           },
1527:           { status: 400 }
1528:         );
1529:       }
1530:     } catch (e: unknown) {
1531:       const errorMessage = e instanceof Error ? e.message : String(e);
1532:       console.error("Error parsing file:", e);
1533:       return NextResponse.json(
1534:         { message: `Failed to parse file content. Error: ${errorMessage}` },
1535:         { status: 500 }
1536:       );
1537:     }
1538: 
1539:     // Run the sanitizer / quality filter / auto-hint
1540:     generatedCards = sanitizeCards(generatedCards);
1541: 
1542:     if (generatedCards.length === 0) {
1543:       return NextResponse.json(
1544:         {
1545:           message:
1546:             "Could not extract any flashcards from this file. The document may not contain clear definitions, terms, or structured slide content. Try a more text-heavy document.",
1547:         },
1548:         { status: 400 }
1549:       );
1550:     }
1551: 
1552:     // Return preview JSON — the frontend will display these for editing
1553:     return NextResponse.json({
1554:       cards: generatedCards,
1555:       fileName: attachment.fileName,
1556:       cardCount: generatedCards.length,
1557:     });
1558:   } catch (error) {
1559:     console.error("Auto-generate flashcards error:", error);
1560:     return NextResponse.json(
1561:       { message: "Internal server error" },
1562:       { status: 500 }
1563:     );
1564:   }
1565: }
