209: export async function DELETE(request: Request) {
210:   const { session, response } = await requireWorkspaceSession();
211:   if (response) return response;
212: 
213:   const roleBlock = requireStudentRole(session.user.role as string);
214:   if (roleBlock) return roleBlock;
215: 
216:   const url = new URL(request.url);
217:   const singleId = url.searchParams.get("id");
218:   const batchIds = url.searchParams.get("ids");
219: 
220:   const idsToDelete: string[] = [];
221: 
222:   if (batchIds) {
223:     idsToDelete.push(...batchIds.split(",").filter(Boolean));
224:   } else if (singleId) {
225:     idsToDelete.push(singleId);
226:   } else {
227:     return NextResponse.json({ message: "Missing card id(s)." }, { status: 400 });
228:   }
229: 
230:   // Verify all cards belong to user's decks
231:   const cards = await db.flashcard.findMany({
232:     where: {
233:       id: { in: idsToDelete },
234:       deck: {
235:         creatorId: session.user.id,
236:         instituteId: session.user.instituteId,
237:       },
238:     },
239:     select: { id: true },
240:   });
241: 
242:   const validIds = cards.map((c) => c.id);
243: 
244:   if (validIds.length === 0) {
245:     return NextResponse.json({ message: "No matching cards found." }, { status: 404 });
246:   }
247: 
248:   await db.flashcard.deleteMany({ where: { id: { in: validIds } } });
249: 
250:   return NextResponse.json({ ok: true, deletedCount: validIds.length });
251: }
