1: import { NextResponse } from "next/server";
2: import { z } from "zod";
3: import { db } from "@/lib/db";
4: import { requireWorkspaceSession } from "../../workspace/_shared";
5: import { grantExp } from "@/lib/gamification/grant-exp";
6: import { EXP_VALUES, DAILY_EXP_CAPS } from "@/lib/gamification/exp-engine";
7: import { awardBadgeIfEarned } from "@/lib/gamification/badge-checker";
8: 
9: export const dynamic = "force-dynamic";
10: 
11: const sessionSchema = z.object({
12:   deckId: z.string().min(1),
13:   cardsReviewed: z.number().int().min(1),
14:   durationSeconds: z.number().min(5),
15: });
16: 
17: export async function POST(request: Request) {
18:   try {
19:     const { session, response } = await requireWorkspaceSession();
20:     if (response) return response;
21: 
22:     const body = await request.json();
23:     const parsed = sessionSchema.safeParse(body);
24: 
25:     if (!parsed.success) {
26:       return NextResponse.json({ message: "Validation failed" }, { status: 400 });
27:     }
28: 
29:     const { deckId, cardsReviewed, durationSeconds } = parsed.data;
30: 
31:     // Verify deck exists
32:     const deck = await db.flashcardDeck.findUnique({
33:       where: { id: deckId },
34:       select: { id: true, title: true, courseId: true },
35:     });
36: 
37:     if (!deck) {
38:       return NextResponse.json({ message: "Deck not found" }, { status: 404 });
39:     }
40: 
41:     // Minimum engagement threshold (≥3 cards and ≥10 seconds duration)
42:     let grantedExp = 0;
43:     let leveledUp = false;
44:     let newLevel = 1;
45: 
46:     if (cardsReviewed >= 3 && durationSeconds >= 10) {
47:       const expRes = await grantExp({
48:         userId: session.user.id,
49:         amount: EXP_VALUES.flashcard_session,
50:         reason: `Flashcard Deck Review: ${deck.title}`,
51:         source: "flashcard",
52:         courseId: deck.courseId ?? undefined,
53:         dailyCap: DAILY_EXP_CAPS.flashcard,
54:       });
55: 
56:       grantedExp = expRes.grantedAmount;
57:       leveledUp = expRes.leveledUp;
58:       newLevel = expRes.newLevel;
59: 
60:       await awardBadgeIfEarned(session.user.id, "flashcard-first");
61:     }
62: 
63:     return NextResponse.json({
64:       success: true,
65:       grantedExp,
66:       leveledUp,
67:       newLevel,
68:     });
69:   } catch (error) {
70:     console.error("FLASHCARD_COMPLETE_SESSION_ERROR", error);
71:     return NextResponse.json({ message: "Internal Server Error" }, { status: 500 });
72:   }
73: }
