11:  * Returns the total page/slide count and slide titles for the page-selector UI
12:  * shown before flashcard generation. Supports PDF and PPTX only.
13:  * TXT / DOCX / CSV return { fileType: "unsupported" } so the UI skips the selector.
14:  */
15: export async function GET(request: Request) {
16:   const { session, response } = await requireWorkspaceSession();
17:   if (response) return response;
18: 
19:   const url = new URL(request.url);
20:   const attachmentId = url.searchParams.get("attachmentId");
21: 
22:   if (!attachmentId) {
23:     return NextResponse.json({ message: "Missing attachmentId" }, { status: 400 });
24:   }
25: 
26:   // Fetch attachment record
27:   const attachment = await db.attachment.findUnique({
28:     where: { id: attachmentId },
29:     include: { syllabusItem: { include: { course: true } } },
30:   });
31: 
32:   if (!attachment || attachment.type !== "FILE") {
33:     return NextResponse.json({ message: "Attachment not found" }, { status: 404 });
34:   }
35: 
36:   // Verify student is enrolled in the course
37:   const courseId = attachment.syllabusItem?.courseId;
38:   if (courseId) {
39:     const enrollment = await db.enrollment.findUnique({
40:       where: { courseId_studentId: { courseId, studentId: session.user.id } },
41:     });
42:     if (!enrollment || enrollment.status !== "APPROVED") {
43:       return NextResponse.json({ message: "Not enrolled" }, { status: 403 });
44:     }
45:   }
46: 
47:   const fileNameLower = attachment.fileName.toLowerCase();
48: 
49:   // Resolve absolute URL for the file
50:   let fileUrl = attachment.url;
51:   if (fileUrl.startsWith("/")) {
52:     const origin = new URL(request.url).origin;
53:     fileUrl = `${origin}${fileUrl}`;
54:   }
55: 
56:   try {
57:     if (fileNameLower.endsWith(".pptx")) {
58:       // ── PPTX: count slides + extract first-title from each ──
59:       const res = await fetch(fileUrl);
60:       if (!res.ok) throw new Error(`Fetch failed: ${res.status}`);
61:       const buffer = Buffer.from(await res.arrayBuffer());
62:       const zip = new AdmZip(buffer);
63: 
64:       interface SlideEntry { entryName: string; getData: () => Buffer }
65:       const slideEntries: SlideEntry[] = (zip.getEntries() as SlideEntry[])
66:         .filter((e) => /^ppt\/slides\/slide\d+\.xml$/i.test(e.entryName))
67:         .sort((a, b) => {
68:           const numOf = (name: string) =>
69:             parseInt(name.match(/slide(\d+)/i)?.[1] ?? "0", 10);
70:           return numOf(a.entryName) - numOf(b.entryName);
71:         });
72: 
73:       const slideTitles: string[] = slideEntries.map((entry) => {
74:         const xml = entry.getData().toString("utf8");
75:         // Extract title shape text
76:         const shapeBlocks = xml.match(/<p:sp\b[^>]*>[\s\S]*?<\/p:sp>/gi) ?? [];
77:         for (const shape of shapeBlocks) {
78:           if (/<p:ph[^>]*type\s*=\s*"(title|ctrTitle)"/i.test(shape)) {
79:             const textNodes = shape.match(/<a:t>([^<]*)<\/a:t>/gi) ?? [];
80:             const title = textNodes
81:               .map((t) => t.replace(/<\/?a:t>/gi, ""))
82:               .join(" ")
83:               .trim();
84:             if (title) return title;
85:           }
86:         }
87:         return ""; // Untitled slide
88:       });
89: 
90:       return NextResponse.json({
91:         fileType: "pptx",
92:         totalSlides: slideEntries.length,
93:         totalPages: null,
94:         slideTitles,
95:       });
96:     }
97: 
98:     if (fileNameLower.endsWith(".pdf")) {
99:       // ── PDF: get total page count from metadata ──
100:       const res = await fetch(fileUrl);
101:       if (!res.ok) throw new Error(`Fetch failed: ${res.status}`);
102:       const buffer = Buffer.from(await res.arrayBuffer());
103:       const pdfParse = require("pdf-parse/lib/pdf-parse.js");
104: 
105:       // Only parse metadata (no text render) to get page count quickly
106:       let totalPages = 0;
107:       await pdfParse(buffer, {
108:         pagerender: (_pageData: unknown) => {
109:           // Count pages without rendering text
110:           return Promise.resolve("");
111:         },
112:       }).then((data: { numpages: number }) => {
113:         totalPages = data.numpages;
114:       });
115: 
116:       return NextResponse.json({
117:         fileType: "pdf",
118:         totalSlides: null,
119:         totalPages,
120:         slideTitles: null,
121:       });
122:     }
123: 
124:     // TXT, DOCX, CSV — no structured page boundaries
125:     return NextResponse.json({
126:       fileType: "unsupported",
127:       totalSlides: null,
128:       totalPages: null,
129:       slideTitles: null,
130:     });
131:   } catch (err) {
132:     console.error("file-info error:", err);
133:     return NextResponse.json(
134:       { message: "Failed to inspect file" },
135:       { status: 500 }
136:     );
137:   }
138: }
139:

