1: import { NextResponse } from "next/server";
2: import { z } from "zod";
3: import { db } from "@/lib/db";
4: import { requireWorkspaceSession } from "../../workspace/_shared";
5: 
6: export const dynamic = "force-dynamic";
7: 
8: function requireStudentRole(role: string): NextResponse | null {
9:   if (role.toUpperCase() !== "STUDENT") {
10:     return NextResponse.json(
11:       { message: "Flashcards are only available to students." },
12:       { status: 403 }
13:     );
14:   }
15:   return null;
16: }
17: 
18: const progressSchema = z.object({
19:   cardId: z.string().min(1),
20:   selfRating: z.enum(["knew_it", "still_learning"]),
21: });
22: 
23: export async function POST(request: Request) {
24:   const { session, response } = await requireWorkspaceSession();
25:   if (response) return response;
26: 
27:   const roleBlock = requireStudentRole(session.user.role as string);
28:   if (roleBlock) return roleBlock;
29: 
30:   const body = await request.json();
31:   const parsed = progressSchema.safeParse(body);
32: 
33:   if (!parsed.success) {
34:     return NextResponse.json(
35:       { message: "Validation failed.", errors: parsed.error.flatten().fieldErrors },
36:       { status: 400 }
37:     );
38:   }
39: 
40:   // Fetch the card and verify it belongs to the user's deck
41:   const card = await db.flashcard.findFirst({
42:     where: {
43:       id: parsed.data.cardId,
44:       deck: {
45:         creatorId: session.user.id,
46:         instituteId: session.user.instituteId,
47:       },
48:     },
49:     select: { id: true, back: true },
50:   });
51: 
52:   if (!card) {
53:     return NextResponse.json({ message: "Card not found." }, { status: 404 });
54:   }
55: 
56:   const isCorrect = parsed.data.selfRating === "knew_it";
57: 
58:   // Upsert progress
59:   const existing = await db.flashcardProgress.findUnique({
60:     where: {
61:       cardId_userId: {
62:         cardId: card.id,
63:         userId: session.user.id,
64:       },
65:     },
66:   });
67: 
68:   if (existing) {
69:     await db.flashcardProgress.update({
70:       where: { id: existing.id },
71:       data: {
72:         status: isCorrect ? "correct" : "incorrect",
73:         attemptCount: existing.attemptCount + 1,
74:         correctCount: isCorrect ? existing.correctCount + 1 : existing.correctCount,
75:         lastAnswer: parsed.data.selfRating,
76:         lastReviewedAt: new Date(),
77:       },
78:     });
79:   } else {
80:     await db.flashcardProgress.create({
81:       data: {
82:         cardId: card.id,
83:         userId: session.user.id,
84:         status: isCorrect ? "correct" : "incorrect",
85:         attemptCount: 1,
86:         correctCount: isCorrect ? 1 : 0,
87:         lastAnswer: parsed.data.selfRating,
88:         lastReviewedAt: new Date(),
89:       },
90:     });
91:   }
92: 
93:   return NextResponse.json({
94:     correct: isCorrect,
95:     correctAnswer: card.back,
96:   });
97: }
98: 
