apps/web/src/app/api/flashcards/study/ro.numberedContent:
1: import { NextResponse } from "next/server";
2: import { db } from "@/lib/db";
3: import { requireWorkspaceSession } from "../../workspace/_shared";
4: 
5: export const dynamic = "force-dynamic";
6: 
7: function requireStudentRole(role: string): NextResponse | null {
8:   if (role.toUpperCase() !== "STUDENT") {
9:     return NextResponse.json(
10:       { message: "Flashcards are only available to students." },
11:       { status: 403 }
12:     );
13:   }
14:   return null;
15: }
16: 
17: /**
18:  * GET /api/flashcards/study?deckId=...
19:  *
20:  * Returns cards prioritized for study:
21:  *   1. "incorrect" cards first (needs review)
22:  *   2. "unseen" cards next (new material)
23:  *   3. "correct" cards last (already mastered)
24:  */
25: export async function GET(request: Request) {
26:   const { session, response } = await requireWorkspaceSession();
27:   if (response) return response;
28: 
29:   const roleBlock = requireStudentRole(session.user.role as string);
30:   if (roleBlock) return roleBlock;
31: 
32:   const url = new URL(request.url);
33:   const deckId = url.searchParams.get("deckId");
34: 
35:   if (!deckId) {
36:     return NextResponse.json({ message: "Missing deckId." }, { status: 400 });
37:   }
38: 
39:   // Verify deck ownership
40:   const deck = await db.flashcardDeck.findFirst({
41:     where: {
42:       id: deckId,
43:       creatorId: session.user.id,
44:       instituteId: session.user.instituteId,
45:     },
46:   });
47: 
48:   if (!deck) {
49:     return NextResponse.json({ message: "Deck not found." }, { status: 404 });
50:   }
51: 
52:   const cards = await db.flashcard.findMany({
53:     where: { deckId },
54:     include: {
55:       progress: {
56:         where: { userId: session.user.id },
57:         select: {
58:           status: true,
59:           attemptCount: true,
60:           correctCount: true,
61:           lastAnswer: true,
62:           lastReviewedAt: true,
63:         },
64:       },
65:     },
66:     orderBy: { orderIndex: "asc" },
67:   });
68: 
69:   // Map and serialize
70:   const serialized = cards.map((card) => {
71:     const prog = card.progress[0] ?? null;
72:     return {
73:       id: card.id,
74:       deckId: card.deckId,
75:       front: card.front,
76:       back: card.back,
77:       hint: card.hint,
78:       attachments: JSON.parse(card.attachments),
79:       orderIndex: card.orderIndex,
80:       progress: prog
81:         ? {
82:             status: prog.status,
83:             attemptCount: prog.attemptCount,
84:             correctCount: prog.correctCount,
85:             lastAnswer: prog.lastAnswer,
86:             lastReviewedAt: prog.lastReviewedAt?.toISOString() ?? null,
87:           }
88:         : undefined,
89:       createdAt: card.createdAt.toISOString(),
90:       updatedAt: card.updatedAt.toISOString(),
91:     };
92:   });
93: 
94:   // Prioritize: incorrect → unseen → correct, then shuffle within each group
95:   const incorrect = serialized.filter((c) => (c.progress?.status ?? "unseen") === "incorrect");
96:   const unseen = serialized.filter((c) => !c.progress || c.progress.status === "unseen");
97:   const correct = serialized.filter((c) => (c.progress?.status ?? "unseen") === "correct");
98: 
99:   // Fisher-Yates shuffle
100:   function shuffle<T>(arr: T[]): T[] {
101:     const a = [...arr];
102:     for (let i = a.length - 1; i > 0; i--) {
103:       const j = Math.floor(Math.random() * (i + 1));
104:       [a[i], a[j]] = [a[j], a[i]];
105:     }
106:     return a;
107:   }
108: 
109:   const sorted = [...shuffle(incorrect), ...shuffle(unseen), ...shuffle(correct)];
110: 
111:   // Compute study stats
112:   const stats = {
113:     totalCards: sorted.length,
114:     correct: correct.length,
115:     incorrect: incorrect.length,
116:     unseen: unseen.length,
117:   };
118: 
119:   return NextResponse.json({ cards: sorted, stats });
120: }
121:

apps/web/src/lib/activity-eligibility.ts.numberedContent:
1: /**
2:  * Activity Eligibility Guard
3:  *
4:  * Single source of truth for determining whether a user can access
5:  * the Interactive Activities feature suite (3D simulations, CodeLab).
6:  *
7:  * RULE: Only users belonging to the Institute of Computer Studies (ICS)
8:  * are eligible. ICS exclusively houses BSIT and BSCpE programs at CDM.
9:  *
10:  * If a Program model is added to the schema in the future, refine the
11:  * check here — every consumer imports from this module, so the change
12:  * propagates automatically.
13:  *
14:  * Used by:
15:  *   - Route layout: apps/web/src/app/(dashboard)/[institute]/activities/layout.tsx
16:  *   - API routes:   apps/web/src/app/api/activities/submit/route.ts
17:  *   - Sidebar:      apps/web/src/components/layout/Sidebar.tsx (conditional nav entry)
18:  */
19: 
20: import { db } from "./db";
21: import { getSession } from "./auth-session";
22: import { normalizeRole } from "./admin-types";
23: 
24: /** The institute code that gates access to Interactive Activities. */
25: const ELIGIBLE_INSTITUTE_CODE = "ics";
26: 
27: /**
28:  * Minimal session shape needed for eligibility checks.
29:  * Avoids coupling to the full Prisma Session type.
30:  */
31: interface EligibilitySession {
32:   user: {
33:     id: string;
34:     role: string;
35:     instituteId: string;
36:   };
37: }
38: 
39: /**
40:  * Checks if a user session is eligible for Interactive Activities.
41:  *
42:  * Eligible when:
43:  *   - The user's institute code is "ics" (Institute of Computer Studies)
44:  *   - Students: must be enrolled under ICS
45:  *   - Instructors: must belong to ICS (they teach ICS courses by definition,
46:  *     since Course.instituteId matches the instructor's institute)
47:  *   - Admins at ICS: eligible (can manage activities)
48:  *
49:  * @param session - A session object containing at least user.id, user.role, user.instituteId
50:  * @returns true if the user may access activity features
51:  */
52: export async function isEligibleForActivities(
53:   session: EligibilitySession
54: ): Promise<boolean> {
55:   // Look up the institute to get its code
56:   const institute = await db.institute.findUnique({
57:     where: { id: session.user.instituteId },
58:     select: { code: true },
59:   });
60: 
61:   if (!institute) return false;
62: 
63:   return institute.code.toLowerCase() === ELIGIBLE_INSTITUTE_CODE;
64: }
65: 
66: /**
67:  * Synchronous eligibility check when institute code is already known.
68:  * Useful in client components where the institute code comes from the route param.
69:  *
70:  * @param instituteCode - The institute code from the URL (e.g. "ics", "ibe")
71:  * @returns true if this institute code qualifies for activity features
72:  */
73: export function isEligibleInstituteCode(instituteCode: string): boolean {
74:   return instituteCode.toLowerCase() === ELIGIBLE_INSTITUTE_CODE;
75: }
76: 
77: /**
78:  * Full eligibility check for API route handlers.
79:  * Reads the session from the cookie, validates it, and checks eligibility.
80:  *
81:  * @returns Object with eligibility result and session, or null if no valid session.
82:  * @throws Never — returns null on auth failure so callers can choose their own error shape.
83:  */
84: export async function checkActivityEligibility(): Promise<{
85:   eligible: boolean;
86:   session: NonNullable<Awaited<ReturnType<typeof getSession>>>;
87:   role: ReturnType<typeof normalizeRole>;
88: } | null> {
89:   const session = await getSession();
90:   if (!session) return null;
91: 
92:   const role = normalizeRole(session.user.role as string);
93:   const eligible = await isEligibleForActivities({
94:     user: {
95:       id: session.user.id,
96:       role: session.user.role as string,
97:       instituteId: session.user.instituteId as string,
98:     },
99:   });
100: 
101:   return { eligible, session, role };
102: }
103:

apps/web/src/lib/admin-types.ts.numberedContent:
1: /**
2:  * Admin System Type Definitions
3:  *
4:  * Central TypeScript interfaces for User Management, RBAC, and Audit logging.
5:  * These types are used across API routes, UI components, and agentic skills.
6:  */
7: 
8: // ─── Role System ───
9: 
10: export type UserRole = 'ADMIN' | 'INSTRUCTOR' | 'STUDENT';
11: 
12: /**
13:  * Maps DB role strings (which may include legacy names like PROFESSOR/TEACHER)
14:  * to the canonical UserRole union.
15:  */
16: export function normalizeRole(role: string): UserRole {
17:   const r = role.toUpperCase();
18:   if (r === 'ADMIN') return 'ADMIN';
19:   if (r === 'PROFESSOR' || r === 'TEACHER' || r === 'INSTRUCTOR') return 'INSTRUCTOR';
20:   return 'STUDENT';
21: }
22: 
23: // ─── User Types ───
24: 
25: export interface LMSUser {
26:   id: string;
27:   email: string;
28:   name: string;
29:   uniqueId: string;
30:   studentNumber?: string | null;
31:   role: UserRole;
32:   isActive: boolean;
33:   permissions: string[];
34:   createdAt: string;
35:   instituteCode?: string;
36: }
37: 
38: // ─── Audit Types ───
39: 
40: export interface AuditLogEntry {
41:   id: string;
42:   adminId: string;
43:   adminName?: string;
44:   targetId: string;
45:   targetName?: string;
46:   action: string;
47:   ipAddress: string;
48:   metadata: Record<string, unknown>;
49:   createdAt: string;
50: }
51: 
52: // ─── Pagination ───
53: 
54: export interface PaginatedResponse<T> {
55:   data: T[];
56:   total: number;
57:   page: number;
58:   pageSize: number;
59:   totalPages: number;
60: }
61: 
62: // ─── Permission System ───
63: 
64: export const SYSTEM_PERMISSIONS = [
65:   'course:create',
66:   'course:archive',
67:   'user:modify',
68:   'grade:export',
69: ] as const;
70: 
71: export type SystemPermission = (typeof SYSTEM_PERMISSIONS)[number];
72: 
73: /** Default permissions assigned when a user is created or their role changes */
74: export const DEFAULT_ROLE_PERMISSIONS: Record<UserRole, SystemPermission[]> = {
75:   ADMIN: ['course:create', 'course:archive', 'user:modify', 'grade:export'],
76:   INSTRUCTOR: ['course:create', 'grade:export'],
77:   STUDENT: [],
78: };
79: 
80: // ─── Audit Action Constants ───
81: 
82: export const AUDIT_ACTIONS = {
83:   ACCOUNT_CREATED: 'ACCOUNT_CREATED',
84:   ACCOUNT_UPDATED: 'ACCOUNT_UPDATED',
85:   ACCOUNT_DELETED: 'ACCOUNT_DELETED',
86:   ACCOUNT_SUSPENSION: 'ACCOUNT_SUSPENSION',
87:   ACCOUNT_REACTIVATION: 'ACCOUNT_REACTIVATION',
88:   ROLE_CHANGE: 'ROLE_CHANGE',
89:   PASSWORD_RESET: 'PASSWORD_RESET',
90:   PERMISSION_CHANGE: 'PERMISSION_CHANGE',
91:   BULK_IMPORT: 'BULK_IMPORT',
92:   PERMISSION_MATRIX_UPDATE: 'PERMISSION_MATRIX_UPDATE',
93: } as const;
94: 
95: export type AuditAction = (typeof AUDIT_ACTIONS)[keyof typeof AUDIT_ACTIONS];
96:

apps/web/src/lib/api-auth.ts.numberedContent:
1: import { db } from './db';
2: import { cookies } from 'next/headers';
3: import { hashToken } from './auth-session';
4: 
5: /**
6:  * Resolves a session from either the lumina_session cookie (web/desktop)
7:  * or the Authorization: Bearer header (mobile).
8:  * Returns the full session with user data, or null.
9:  */
10: export async function getSessionFromRequest(request?: Request) {
11:   // 1. Try cookie first (web/desktop path)
12:   try {
13:     const cookieStore = await cookies();
14:     const cookieToken = cookieStore.get('lumina_session')?.value;
15:     if (cookieToken) {
16:       const session = await validateToken(cookieToken);
17:       if (session) return session;
18:     }
19:   } catch {
20:     // cookies() throws in non-cookie contexts, fall through to bearer
21:   }
22: 
23:   // 2. Try Bearer token (mobile path)
24:   if (request) {
25:     const authHeader = request.headers.get('Authorization');
26:     if (authHeader?.startsWith('Bearer ')) {
27:       const token = authHeader.slice(7).trim();
28:       const session = await validateToken(token);
29:       if (session) return session;
30:     }
31:   }
32: 
33:   return null;
34: }
35: 
36: async function validateToken(rawToken: string) {
37:   if (!rawToken) return null;
38: 
39:   try {
40:     const tokenHash = hashToken(rawToken);
41: 
42:     const session = await db.session.findFirst({
43:       where: {
44:         OR: [{ tokenHash }, { id: rawToken }],
45:       },
46:       include: {
47:         user: {
48:           include: { institute: true },
49:         },
50:       },
51:     });
52: 
53:     if (!session) return null;
54: 
55:     if (session.expiresAt.getTime() < Date.now()) {
56:       await db.session.delete({ where: { id: session.id } }).catch(() => {});
57:       return null;
58:     }
59: 
60:     const user = session.user as Record<string, unknown>;
61:     if (user.isActive === false) {
62:       await db.session.delete({ where: { id: session.id } }).catch(() => {});
63:       return null;
64:     }
65: 
66:     return session;
67:   } catch {
68:     return null;
69:   }
70: }
71:

apps/web/src/lib/auth-session.ts.numberedContent:
1: import { db } from "./db";
2: import { cookies, headers } from "next/headers";
3: import crypto from "crypto";
4: 
5: /**
6:  * Computes a SHA-256 digest of an opaque bearer token.
7:  * Only this hash is stored and looked up in the database.
8:  */
9: export function hashToken(token: string): string {
10:   return crypto.createHash("sha256").update(token).digest("hex");
11: }
12: 
13: export interface CreateSessionResult {
14:   sessionId: string;
15:   token: string;
16:   expiresAt: Date;
17: }
18: 
19: /**
20:  * Creates a real database-backed session for the user using a 256-bit CSPRNG opaque token.
21:  * Returns the raw token for client credentials while storing only the SHA-256 hash in PostgreSQL.
22:  */
23: export async function createSession(
24:   userId: string,
25:   metadata?: { userAgent?: string; ipAddress?: string }
26: ): Promise<CreateSessionResult> {
27:   // 7-day session validity
28:   const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);
29: 
30:   // Generate 256 bits of cryptographic entropy
31:   const rawToken = crypto.randomBytes(32).toString("base64url");
32:   const tokenHash = hashToken(rawToken);
33: 
34:   const session = await db.session.create({
35:     data: {
36:       tokenHash,
37:       userId,
38:       expiresAt,
39:       userAgent: metadata?.userAgent,
40:       ipAddress: metadata?.ipAddress,
41:     },
42:   });
43: 
44:   const cookieStore = await cookies();
45:   cookieStore.set("lumina_session", rawToken, {
46:     httpOnly: true,
47:     secure: process.env.NODE_ENV === "production",
48:     sameSite: "lax",
49:     expires: expiresAt,
50:     path: "/",
51:   });
52: 
53:   return {
54:     sessionId: session.id,
55:     token: rawToken,
56:     expiresAt,
57:   };
58: }
59: 
60: /**
61:  * Validates the session from the lumina_session cookie or Authorization: Bearer header.
62:  * Hashes the incoming opaque token and verifies matching session in the database.
63:  * If expired or invalid, clears the cookie (if present) and returns null.
64:  */
65: export async function getSession() {
66:   let rawToken: string | undefined;
67:   let isCookie = false;
68: 
69:   try {
70:     const cookieStore = await cookies();
71:     rawToken = cookieStore.get("lumina_session")?.value;
72:     if (rawToken) {
73:       isCookie = true;
74:     }
75:   } catch {
76:     // cookies() might throw in non-request contexts
77:   }
78: 
79:   if (!rawToken) {
80:     try {
81:       const headerStore = await headers();
82:       const authHeader = headerStore.get("authorization");
83:       if (authHeader?.startsWith("Bearer ")) {
84:         rawToken = authHeader.slice(7).trim();
85:       }
86:     } catch {
87:       // headers() might throw in non-request contexts
88:     }
89:   }
90: 
91:   if (!rawToken) return null;
92: 
93:   try {
94:     const tokenHash = hashToken(rawToken);
95: 
96:     // Look up session by tokenHash (or fallback to id for transition backwards-compatibility)
97:     const session = await db.session.findFirst({
98:       where: {
99:         OR: [{ tokenHash }, { id: rawToken }],
100:       },
101:       include: {
102:         user: {
103:           include: { institute: true },
104:         },
105:       },
106:     });
107: 
108:     if (!session) {
109:       return null;
110:     }
111: 
112:     if (session.expiresAt.getTime() < Date.now()) {
113:       // Session expired, purge from database
114:       await db.session.delete({ where: { id: session.id } }).catch(() => {});
115:       if (isCookie) {
116:         try {
117:           const cookieStore = await cookies();
118:           cookieStore.delete("lumina_session");
119:         } catch {}
120:       }
121:       return null;
122:     }
123: 
124:     // Check if user account is active
125:     const user = session.user as Record<string, unknown>;
126:     if (user.isActive === false) {
127:       // Purge session for deactivated user
128:       await db.session.delete({ where: { id: session.id } }).catch(() => {});
129:       if (isCookie) {
130:         try {
131:           const cookieStore = await cookies();
132:           cookieStore.delete("lumina_session");
133:         } catch {}
134:       }
135:       return null;
136:     }
137: 
138:     return session;
139:   } catch (error) {
140:     console.error("Session lookup error", error);
141:     return null;
142:   }
143: }
144: 
145: /**
146:  * Deletes the session from the database and clears the lumina_session cookie.
147:  * Accepts optional tokenOverride for Bearer tokens sent from mobile/desktop clients.
148:  */
149: export async function deleteSession(tokenOverride?: string) {
150:   let rawToken = tokenOverride;
151: 
152:   try {
153:     const cookieStore = await cookies();
154:     if (!rawToken) {
155:       rawToken = cookieStore.get("lumina_session")?.value;
156:     }
157:     cookieStore.delete("lumina_session");
158:   } catch {
159:     // Non-cookie environment
160:   }
161: 
162:   if (rawToken) {
163:     try {
164:       const tokenHash = hashToken(rawToken);
165:       // Delete matching session by tokenHash or id in a single query
166:       await db.session.deleteMany({
167:         where: {
168:           OR: [{ tokenHash }, { id: rawToken }],
169:         },
170:       });
171:     } catch (error) {
172:       console.error("Error deleting session from DB:", error);
173:     }
174:   }
175: }
