apps/web/src/lib/rbac.ts.numberedContent:
1: /**
2:  * Role-Based Access Control (RBAC) Module
3:  *
4:  * Provides permission checking, role normalization, session guards,
5:  * and re-authentication utilities for the admin system.
6:  */
7: 
8: import { db } from './db';
9: import { getSession } from './auth-session';
10: import { compare } from 'bcryptjs';
11: import {
12:   normalizeRole,
13:   DEFAULT_ROLE_PERMISSIONS,
14:   type UserRole,
15:   type SystemPermission,
16: } from './admin-types';
17: 
18: // Re-export for convenience
19: export { normalizeRole } from './admin-types';
20: 
21: // ─── Permission Helpers ───
22: 
23: /**
24:  * Parses the JSON permissions string stored in the database.
25:  * Returns an empty array on parse failure.
26:  */
27: export function parsePermissions(raw: string): string[] {
28:   try {
29:     const parsed = JSON.parse(raw);
30:     return Array.isArray(parsed) ? parsed : [];
31:   } catch {
32:     return [];
33:   }
34: }
35: 
36: /**
37:  * Checks if a user's permission array includes the required permission.
38:  */
39: export function hasPermission(
40:   permissions: string[],
41:   required: SystemPermission
42: ): boolean {
43:   return permissions.includes(required);
44: }
45: 
46: /**
47:  * Returns the default permission set for a given role.
48:  */
49: export function getDefaultPermissions(role: UserRole): SystemPermission[] {
50:   return DEFAULT_ROLE_PERMISSIONS[role] ?? [];
51: }
52: 
53: // ─── Session Guards ───
54: 
55: export interface AdminSession {
56:   sessionId: string;
57:   user: {
58:     id: string;
59:     name: string;
60:     email: string;
61:     role: string;
62:     isActive: boolean;
63:     permissions: string;
64:     instituteId: string;
65:   };
66: }
67: 
68: /**
69:  * Validates the current session and returns it.
70:  * Returns null if no valid session exists.
71:  */
72: export async function getValidSession(): Promise<AdminSession | null> {
73:   const session = await getSession();
74:   if (!session) return null;
75: 
76:   return {
77:     sessionId: session.id,
78:     user: {
79:       id: session.user.id,
80:       name: session.user.name,
81:       email: session.user.email,
82:       role: session.user.role,
83:       isActive: (session.user as Record<string, unknown>).isActive !== false,
84:       permissions: ((session.user as Record<string, unknown>).permissions as string) ?? '[]',
85:       instituteId: session.user.instituteId,
86:     },
87:   };
88: }
89: 
90: /**
91:  * Requires the current user to be an authenticated ADMIN.
92:  * Returns the session or throws a Response-compatible error object.
93:  */
94: export async function requireAdmin(): Promise<AdminSession> {
95:   const session = await getValidSession();
96: 
97:   if (!session) {
98:     throw { status: 401, message: 'Authentication required.' };
99:   }
100: 
101:   const role = normalizeRole(session.user.role);
102:   if (role !== 'ADMIN') {
103:     throw { status: 403, message: 'Forbidden: Admin access required.' };
104:   }
105: 
106:   if (!session.user.isActive) {
107:     throw { status: 403, message: 'Your account has been deactivated. Please contact administration.' };
108:   }
109: 
110:   return session;
111: }
112: 
113: /**
114:  * Requires the current user to have a specific permission.
115:  */
116: export async function requirePermission(
117:   permission: SystemPermission
118: ): Promise<AdminSession> {
119:   const session = await getValidSession();
120: 
121:   if (!session) {
122:     throw { status: 401, message: 'Authentication required.' };
123:   }
124: 
125:   if (!session.user.isActive) {
126:     throw { status: 403, message: 'Your account has been deactivated. Please contact administration.' };
127:   }
128: 
129:   const role = normalizeRole(session.user.role);
130:   if (role === 'ADMIN') return session; // Admins always pass
131: 
132:   const userPermissions = parsePermissions(session.user.permissions);
133:   if (!hasPermission(userPermissions, permission)) {
134:     throw { status: 403, message: `Forbidden: Missing permission '${permission}'.` };
135:   }
136: 
137:   return session;
138: }
139: 
140: /**
141:  * Re-authentication check for sensitive operations (e.g., role changes).
142:  * Requires the admin to provide their current password.
143:  */
144: export async function requireReAuth(
145:   adminId: string,
146:   password: string
147: ): Promise<boolean> {
148:   const admin = await db.user.findUnique({
149:     where: { id: adminId },
150:     select: { password: true },
151:   });
152: 
153:   if (!admin) {
154:     throw { status: 404, message: 'Admin user not found.' };
155:   }
156: 
157:   const valid = await compare(password, admin.password);
158:   if (!valid) {
159:     throw { status: 401, message: 'Re-authentication failed. Incorrect password.' };
160:   }
161: 
162:   return true;
163: }
164: 
165: // ─── Audit Logging ───
166: 
167: /**
168:  * Creates an immutable audit log entry.
169:  */
170: export async function createAuditLog(params: {
171:   adminId: string;
172:   targetId: string;
173:   action: string;
174:   ipAddress?: string;
175:   metadata?: Record<string, unknown>;
176: }): Promise<void> {
177:   await db.auditLog.create({
178:     data: {
179:       adminId: params.adminId,
180:       targetId: params.targetId,
181:       action: params.action,
182:       ipAddress: params.ipAddress ?? '',
183:       metadata: params.metadata ? JSON.stringify(params.metadata) : '{}',
184:     },
185:   });
186: }
187: 
188: /**
189:  * Extracts the client IP address from request headers.
190:  */
191: export function getClientIp(request: Request): string {
192:   const forwarded = request.headers.get('x-forwarded-for');
193:   if (forwarded) {
194:     return forwarded.split(',')[0].trim();
195:   }
196:   const realIp = request.headers.get('x-real-ip');
197:   return realIp ?? '127.0.0.1';
198: }
